const COURSE={"id":"career-fluency","title":"English Communication & Career Fluency","level":"A2+ → B1","module":1,"moduleTitle":"Fluency Foundations","moduleGoal":"Build automatic speaking habits, natural conversation control and clear professional self-expression.","lessons":[{"id":"w1l1","number":1,"week":1,"title":"Your starting point","outcome":"Complete a friendly speaking diagnostic and identify one clear fluency goal.","expressions":[{"text":"Let me think for a moment.","job":"gain thinking time without becoming silent","cloze":"___ me think for a moment.","answer":"Let","choices":["Let","Make","Give"]},{"text":"What I mean is…","job":"restate an idea more clearly","cloze":"What I ___ is…","answer":"mean","choices":["mean","say","tell"]},{"text":"Could you repeat the question?","job":"ask to hear a question again","cloze":"Could you ___ the question?","answer":"repeat","choices":["repeat","return","reply"]},{"text":"In my experience…","job":"connect an answer to real life","cloze":"In my ___…","answer":"experience","choices":["experience","example","opinion"]},{"text":"One goal I have is…","job":"state a learning or career goal","cloze":"One ___ I have is…","answer":"goal","choices":["goal","job","reason"]}],"grammar":{"focus":"Complete simple sentences, question forms, and infinitives for goals.","items":[{"q":"Choose the complete sentence.","options":["I use English at work.","I English at work.","Use English work."],"answer":"I use English at work.","tag":"grammar:complete-sentence"},{"q":"Choose the accurate question.","options":["Where do you use English?","Where you use English?","Where does you use English?"],"answer":"Where do you use English?","tag":"grammar:question-form"},{"q":"Choose the accurate goal sentence.","options":["I want to speak more confidently.","I want speak more confidently.","I want speaking more confidently."],"answer":"I want to speak more confidently.","tag":"grammar:infinitive"},{"q":"Choose the correct sentence.","options":["I feel confident when I read.","I feels confident when I read.","I feeling confident when I read."],"answer":"I feel confident when I read.","tag":"grammar:present-simple"},{"q":"Complete: One thing I ___ well is reading.","options":["do","does","doing"],"answer":"do","tag":"grammar:do"},{"q":"Choose the correct negative.","options":["I do not use English every day.","I not use English every day.","I does not use English every day."],"answer":"I do not use English every day.","tag":"grammar:negative"},{"q":"Choose the best question for a goal.","options":["What would you like to improve?","What you would like improve?","What would like you improve?"],"answer":"What would you like to improve?","tag":"grammar:question-order"},{"q":"Complete: My main difficulty ___ speaking quickly.","options":["is","are","be"],"answer":"is","tag":"grammar:be"},{"q":"Choose the accurate time phrase.","options":["In twelve weeks, I want to improve.","At twelve weeks, I want improve.","On twelve weeks, I improving."],"answer":"In twelve weeks, I want to improve.","tag":"grammar:time-phrase"},{"q":"Choose the best combined sentence.","options":["I can read well, but spontaneous speaking is harder.","I can read well, because spontaneous speaking is harder.","I can read well, so spontaneous speaking is harder."],"answer":"I can read well, but spontaneous speaking is harder.","tag":"grammar:connector"}]},"listening":{"title":"My English starting point","questions":[{"q":"What is the speaker mainly describing?","options":["Their current English ability and one goal","A holiday plan","A new job offer"],"answer":"Their current English ability and one goal","tag":"listening:main-idea"},{"q":"Where does the speaker use English at work?","options":["Reading messages and speaking with colleagues","Only writing essays","Only answering phone calls"],"answer":"Reading messages and speaking with colleagues","tag":"listening:detail"},{"q":"What does the speaker do online?","options":["Watches videos and searches for information","Teaches a class","Buys airline tickets"],"answer":"Watches videos and searches for information","tag":"listening:detail"},{"q":"Which skill feels comfortable?","options":["Reading","Spontaneous speaking","Giving presentations"],"answer":"Reading","tag":"listening:detail"},{"q":"What happens when the speaker must answer quickly?","options":["They sometimes pause too long","They always change the topic","They speak much faster"],"answer":"They sometimes pause too long","tag":"listening:detail"},{"q":"Why does the speaker pause?","options":["They are searching for the right word","They are bored","They cannot hear the question"],"answer":"They are searching for the right word","tag":"listening:inference"},{"q":"When does the speaker communicate better?","options":["When they have a few seconds to think","When they read a full script","When they avoid questions"],"answer":"When they have a few seconds to think","tag":"listening:detail"},{"q":"What is the twelve-week speaking goal?","options":["Speak for two minutes with fewer stops","Write a ten-page report","Learn one hundred grammar rules"],"answer":"Speak for two minutes with fewer stops","tag":"listening:goal"},{"q":"What strategy does the speaker want to use confidently?","options":["Ask for repetition","Avoid difficult questions","Translate every sentence"],"answer":"Ask for repetition","tag":"listening:strategy"},{"q":"Which phrase best summarizes the message?","options":["Know your starting point, then set a measurable goal.","Perfect grammar must come first.","Only reading matters for fluency."],"answer":"Know your starting point, then set a measurable goal.","tag":"listening:inference"}]},"writing":{"tasks":[{"prompt":"Write one sentence about where you use English.","minWords":5},{"prompt":"Write one sentence about a skill you already do well.","minWords":5},{"prompt":"Write one sentence about a speaking situation that feels difficult.","minWords":5},{"prompt":"Write a complete question you could ask a teacher about your English.","minWords":5},{"prompt":"Use “In my experience…” in a true sentence.","minWords":5},{"prompt":"Use “One goal I have is…” to state a measurable goal.","minWords":8},{"prompt":"Explain why that goal matters to you in 2–3 sentences.","minWords":15},{"prompt":"Describe one situation where you need English and what usually happens.","minWords":20},{"prompt":"Draft stage: Write a short 40–60 word self-diagnostic: strength, difficulty, and strategy.","minWords":40},{"prompt":"Final rewrite and transfer: write a 70–90 word starting-point profile that you can use to prepare your two-minute baseline.","minWords":70}]},"review":{"keywords":"use · strength · difficulty · goal","mission":"Speak for two minutes about who you are, how you use English, and what you want to achieve in twelve weeks."}},{"id":"w1l2","number":2,"week":1,"title":"A strong professional introduction","outcome":"Introduce yourself with a clear beginning, useful details and a forward-looking ending.","expressions":[{"text":"I currently work as…","job":"state your present role","cloze":"I ___ work as…","answer":"currently","choices":["currently","current","currency"]},{"text":"My background is in…","job":"describe education or professional field","cloze":"My ___ is in…","answer":"background","choices":["background","back","history"]},{"text":"I’m responsible for…","job":"explain a main duty","cloze":"I’m ___ for…","answer":"responsible","choices":["responsible","response","responsibility"]},{"text":"I’m particularly interested in…","job":"name a professional interest","cloze":"I’m ___ interested in…","answer":"particularly","choices":["particularly","particular","partly"]},{"text":"My current goal is to…","job":"finish with a future direction","cloze":"My ___ goal is to…","answer":"current","choices":["current","currently","career"]}],"grammar":{"focus":"Present simple with be, have and work; gerunds after “responsible for”; because for reasons.","items":[{"q":"Choose the accurate role sentence.","options":["I currently work as a project assistant.","I currently works as a project assistant.","I am currently work as a project assistant."],"answer":"I currently work as a project assistant.","tag":"grammar:present-simple"},{"q":"Choose the correct background sentence.","options":["My background is in education.","My background are in education.","My background in is education."],"answer":"My background is in education.","tag":"grammar:be"},{"q":"Choose the correct responsibility sentence.","options":["I’m responsible for preparing reports.","I’m responsible to prepare reports.","I responsible for preparing reports."],"answer":"I’m responsible for preparing reports.","tag":"grammar:gerund"},{"q":"Choose the best reason.","options":["I enjoy my role because I solve problems.","I enjoy my role because of I solve problems.","I enjoy my role because solve problems."],"answer":"I enjoy my role because I solve problems.","tag":"grammar:because"},{"q":"Complete: I ___ two main responsibilities.","options":["have","has","having"],"answer":"have","tag":"grammar:have"},{"q":"Choose the correct subject-verb agreement.","options":["She works with international clients.","She work with international clients.","She working with international clients."],"answer":"She works with international clients.","tag":"grammar:third-person"},{"q":"Complete: My current goal is ___ lead a larger team.","options":["to","for","at"],"answer":"to","tag":"grammar:infinitive"},{"q":"Choose the natural sentence.","options":["I’m particularly interested in digital education.","I particularly interested digital education.","I’m particular interest in digital education."],"answer":"I’m particularly interested in digital education.","tag":"grammar:collocation"},{"q":"Choose the correct question.","options":["What are you responsible for?","What you are responsible for?","What do responsible you for?"],"answer":"What are you responsible for?","tag":"grammar:question-form"},{"q":"Choose the best ending.","options":["My current goal is to improve my leadership skills.","My current goal improve leadership skills.","My current goal is improving to leadership skills."],"answer":"My current goal is to improve my leadership skills.","tag":"grammar:infinitive"}]},"listening":{"title":"A professional introduction","questions":[{"q":"What is Hassan’s current role?","options":["Project assistant","Site supervisor","English teacher"],"answer":"Project assistant","tag":"listening:detail"},{"q":"What is his professional background?","options":["Construction planning","Medicine","Accounting"],"answer":"Construction planning","tag":"listening:detail"},{"q":"How long has he worked with the team?","options":["Almost two years","Ten years","Two months"],"answer":"Almost two years","tag":"listening:detail"},{"q":"Which task is one of his responsibilities?","options":["Preparing weekly updates","Teaching mathematics","Selling construction materials"],"answer":"Preparing weekly updates","tag":"listening:detail"},{"q":"Why is he interested in planning?","options":["He likes turning complicated projects into clear steps","He wants to avoid teamwork","He dislikes project information"],"answer":"He likes turning complicated projects into clear steps","tag":"listening:reason"},{"q":"Who does he work closely with?","options":["Engineers and site supervisors","Only customers","School teachers"],"answer":"Engineers and site supervisors","tag":"listening:detail"},{"q":"Why is communication important in his role?","options":["He works with different project colleagues","He never shares information","He works alone"],"answer":"He works with different project colleagues","tag":"listening:inference"},{"q":"What is his future career goal?","options":["Lead larger projects","Leave construction immediately","Study medicine"],"answer":"Lead larger projects","tag":"listening:goal"},{"q":"What English ability does he want to improve?","options":["Communicate confidently and explain project information clearly","Read only fiction","Memorize grammar terminology"],"answer":"Communicate confidently and explain project information clearly","tag":"listening:detail"},{"q":"Which order best matches the introduction?","options":["Role → background → responsibilities → interest → goal","Goal → hobby → family → role","Problem → apology → goodbye"],"answer":"Role → background → responsibilities → interest → goal","tag":"listening:sequence"}]},"writing":{"tasks":[{"prompt":"Write your current role or study status in one complete sentence.","minWords":5},{"prompt":"Write one sentence beginning “My background is in…”","minWords":5},{"prompt":"Write one responsibility using “I’m responsible for…”","minWords":5},{"prompt":"Write one sentence about a professional interest.","minWords":5},{"prompt":"Write one sentence about your current career goal.","minWords":5},{"prompt":"Add a reason using “because”.","minWords":8},{"prompt":"Write 2–3 sentences explaining your role to a new colleague.","minWords":18},{"prompt":"Write a short introduction that includes role, background and responsibility.","minWords":30},{"prompt":"Draft stage: Add your professional interest and future goal to make a 50–70 word introduction.","minWords":50},{"prompt":"Final rewrite and transfer: write an 80–100 word professional introduction with a clear beginning, development and forward-looking ending.","minWords":80}]},"review":{"keywords":"role · background · responsibility · interest · goal","mission":"Deliver a 90-second professional introduction without reading full sentences."}},{"id":"w1l3","number":3,"week":1,"title":"Keep speaking without long pauses","outcome":"Use thinking phrases, connectors and repair strategies to maintain your turn.","expressions":[{"text":"There are two main reasons.","job":"organise an answer before giving details","cloze":"There are two main ___.","answer":"reasons","choices":["reasons","results","examples"]},{"text":"The first point is…","job":"start your first idea","cloze":"The first ___ is…","answer":"point","choices":["point","place","part"]},{"text":"Another thing is…","job":"add a second idea","cloze":"Another ___ is…","answer":"thing","choices":["thing","reasoning","exampled"]},{"text":"For example…","job":"support an idea with evidence","cloze":"For ___…","answer":"example","choices":["example","reason","case"]},{"text":"Let me say that another way.","job":"repair an unclear sentence","cloze":"Let me say that another ___.","answer":"way","choices":["way","word","time"]}],"grammar":{"focus":"Join ideas with and, but, because and so; organise two-point answers.","items":[{"q":"Choose the best connector: I use English at work ___ I speak with international clients.","options":["because","but","so"],"answer":"because","tag":"grammar:connector-because"},{"q":"Choose the best connector: I understand the topic, ___ I sometimes need more time to answer.","options":["but","because","so"],"answer":"but","tag":"grammar:connector-but"},{"q":"Choose the best connector: I want to work internationally, ___ I practise English every day.","options":["so","but","because"],"answer":"so","tag":"grammar:connector-so"},{"q":"Choose the sentence that adds information.","options":["I read articles and I watch videos.","I read articles but I watch videos because.","I read articles so but videos."],"answer":"I read articles and I watch videos.","tag":"grammar:connector-and"},{"q":"Choose the best organised opening.","options":["There are two main reasons.","Because two reasons are.","Two main there reasons."],"answer":"There are two main reasons.","tag":"grammar:organisation"},{"q":"Complete: The first point ___ communication at work.","options":["is","are","be"],"answer":"is","tag":"grammar:be"},{"q":"Choose the best example sentence.","options":["For example, I speak with international visitors.","For example because I speak international visitors.","Example for I speak visitors."],"answer":"For example, I speak with international visitors.","tag":"grammar:example"},{"q":"Choose the best repair.","options":["Let me say that another way.","Let me saying another way.","Let me to say another way."],"answer":"Let me say that another way.","tag":"grammar:repair-phrase"},{"q":"Choose the strongest two-point structure.","options":["The first point is confidence. Another thing is career growth.","First confidence another career.","The point first because career another."],"answer":"The first point is confidence. Another thing is career growth.","tag":"grammar:organisation"},{"q":"Choose the correctly linked sentence.","options":["English is difficult sometimes, but I keep practising because it matters to my career.","English difficult but because career so.","English is difficult because but I practise."],"answer":"English is difficult sometimes, but I keep practising because it matters to my career.","tag":"grammar:connectors"}]},"listening":{"title":"Why English matters to me","questions":[{"q":"How many main reasons does the speaker give?","options":["Two","Three","One"],"answer":"Two","tag":"listening:main-idea"},{"q":"What is the first reason?","options":["Communication at work","Travel for holidays","Reading novels"],"answer":"Communication at work","tag":"listening:sequence"},{"q":"Who does the speaker sometimes meet?","options":["People from different countries","Only family members","Only classmates"],"answer":"People from different countries","tag":"listening:detail"},{"q":"What example does the speaker give?","options":["Speaking with a visitor about a project schedule","Writing a school exam","Buying a new phone"],"answer":"Speaking with a visitor about a project schedule","tag":"listening:detail"},{"q":"What problem happened during that conversation?","options":["The speaker paused too often","The visitor left immediately","The speaker forgot the project"],"answer":"The speaker paused too often","tag":"listening:detail"},{"q":"What is the second reason?","options":["Career growth","Better handwriting","More free time"],"answer":"Career growth","tag":"listening:sequence"},{"q":"Which opportunities are mentioned?","options":["Training, interviews and more responsibility","Driving lessons and sports","Cooking and shopping"],"answer":"Training, interviews and more responsibility","tag":"listening:detail"},{"q":"What does “Let me say that another way” signal?","options":["The speaker is repairing or clarifying an idea","The speaker is ending the conversation","The speaker is asking a question"],"answer":"The speaker is repairing or clarifying an idea","tag":"listening:strategy"},{"q":"What does the speaker say they do NOT need before speaking?","options":["Perfect English","Useful language","Practice"],"answer":"Perfect English","tag":"listening:inference"},{"q":"What practice strategy does the speaker prefer?","options":["Short answers, examples and repair phrases","Long memorized scripts only","Avoiding difficult topics"],"answer":"Short answers, examples and repair phrases","tag":"listening:strategy"}]},"writing":{"tasks":[{"prompt":"Write one reason English matters to you.","minWords":5},{"prompt":"Add a second reason using “Another thing is…”","minWords":5},{"prompt":"Write one example beginning “For example…”","minWords":5},{"prompt":"Join two ideas with “and”.","minWords":5},{"prompt":"Join two contrasting ideas with “but”.","minWords":5},{"prompt":"Explain one reason using “because”.","minWords":8},{"prompt":"Write a 3-sentence answer with two reasons and one example.","minWords":20},{"prompt":"Write a repair sentence using “Let me say that another way.”","minWords":10},{"prompt":"Draft stage: Write a 50–70 word answer to “Why are you learning English now?”","minWords":50},{"prompt":"Final rewrite and transfer: write an 80–100 word two-point response that you could later deliver as a two-minute talk.","minWords":80}]},"review":{"keywords":"reason 1 · example · reason 2 · repair","mission":"Speak for two minutes: “Why I am learning English now.” Repeat with fewer pauses."}},{"id":"w2l4","number":4,"week":2,"title":"Start conversations naturally","outcome":"Open a conversation in social and professional situations.","expressions":[{"text":"How has your day been so far?","job":"open a relaxed conversation","cloze":"How has your ___ been so far?","answer":"day","choices":["day","work","time"]},{"text":"What brings you here?","job":"ask about purpose at an event","cloze":"What ___ you here?","answer":"brings","choices":["brings","takes","makes"]},{"text":"Have we met before?","job":"check whether you know someone","cloze":"Have we ___ before?","answer":"met","choices":["met","meet","meeting"]},{"text":"How do you know the team?","job":"find a shared connection","cloze":"How do you ___ the team?","answer":"know","choices":["know","knows","knowing"]},{"text":"That sounds interesting.","job":"respond positively before another question","cloze":"That ___ interesting.","answer":"sounds","choices":["sounds","hears","listens"]}],"grammar":{"focus":"Wh- questions, present simple question order, and present perfect for “Have we met…?”","items":[{"q":"Choose the correct opener.","options":["What brings you here?","What you brings here?","What does brings you here?"],"answer":"What brings you here?","tag":"grammar:wh-question"},{"q":"Choose the correct question.","options":["How do you know the team?","How you know the team?","How does you know team?"],"answer":"How do you know the team?","tag":"grammar:question-order"},{"q":"Choose the correct present perfect question.","options":["Have we met before?","Did we met before?","Have we meet before?"],"answer":"Have we met before?","tag":"grammar:present-perfect"},{"q":"Complete: How ___ your day been so far?","options":["has","have","do"],"answer":"has","tag":"grammar:auxiliary"},{"q":"Choose the natural response.","options":["That sounds interesting.","That sound interesting.","That is sound interesting."],"answer":"That sounds interesting.","tag":"grammar:third-person"},{"q":"Choose the safe professional question.","options":["What brings you to this workshop?","How much money do you earn?","Why are you still single?"],"answer":"What brings you to this workshop?","tag":"grammar:appropriacy"},{"q":"Choose the correct present simple question.","options":["Where do you work?","Where you work?","Where does you work?"],"answer":"Where do you work?","tag":"grammar:present-simple-question"},{"q":"Complete: How ___ you know the organiser?","options":["do","are","have"],"answer":"do","tag":"grammar:auxiliary"},{"q":"Choose the best follow-up.","options":["What kind of work do you do?","What kind work you do?","What work does you do?"],"answer":"What kind of work do you do?","tag":"grammar:question-order"},{"q":"Choose the correct sentence.","options":["I’m attending the workshop today.","I attending workshop today.","I am attend the workshop today."],"answer":"I’m attending the workshop today.","tag":"grammar:present-continuous"}]},"listening":{"title":"Meeting someone at a workshop","questions":[{"q":"Where does the conversation happen?","options":["At a digital skills workshop","At a hospital","At a football match"],"answer":"At a digital skills workshop","tag":"listening:setting"},{"q":"What is the first question the woman asks?","options":["Have we met before?","Where do you live?","How old are you?"],"answer":"Have we met before?","tag":"listening:sequence"},{"q":"Why is the speaker at the workshop?","options":["To learn more about technology at work","To buy a phone","To meet a doctor"],"answer":"To learn more about technology at work","tag":"listening:detail"},{"q":"How does the woman react?","options":["That sounds interesting.","That is impossible.","I do not care."],"answer":"That sounds interesting.","tag":"listening:detail"},{"q":"What does she ask next?","options":["How the speaker knows the organising team","How much the speaker earns","Where the speaker was born"],"answer":"How the speaker knows the organising team","tag":"listening:detail"},{"q":"Why do the questions feel natural?","options":["They connect to the event and are not too personal","They are very private","They change topics quickly"],"answer":"They connect to the event and are not too personal","tag":"listening:inference"},{"q":"What does the speaker later ask about?","options":["The woman’s work","Her salary","Her family problems"],"answer":"The woman’s work","tag":"listening:detail"},{"q":"What shared connection do they discover?","options":["Someone from the same community project","The same school teacher","The same house"],"answer":"Someone from the same community project","tag":"listening:detail"},{"q":"What helps the conversation continue?","options":["Each question creates a shared topic","They both read from a script","They avoid asking questions"],"answer":"Each question creates a shared topic","tag":"listening:inference"},{"q":"What is the main lesson?","options":["Use safe, connected opening questions.","Ask personal questions first.","Speak without listening."],"answer":"Use safe, connected opening questions.","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write one safe opening question for a workshop.","minWords":5},{"prompt":"Write one safe opening question for an online meeting.","minWords":5},{"prompt":"Write a friendly response to someone’s answer.","minWords":5},{"prompt":"Write a question beginning “What brings you…”","minWords":5},{"prompt":"Write a question beginning “How do you know…”","minWords":5},{"prompt":"Write a two-line opening exchange.","minWords":10},{"prompt":"Write three connected questions for meeting a new colleague.","minWords":18},{"prompt":"Explain why one personal question might be inappropriate in a professional setting.","minWords":20},{"prompt":"Draft stage: Write a 50–70 word mini-conversation that starts naturally and reaches a shared topic.","minWords":50},{"prompt":"Final rewrite and transfer: write three different conversation openings for three situations: workshop, office reception and online meeting.","minWords":70}]},"review":{"keywords":"opening · safe question · shared topic · follow-up","mission":"Start three different two-minute conversations without using the same opening twice."}},{"id":"w2l5","number":5,"week":2,"title":"Show interest and ask follow-ups","outcome":"Keep a conversation going by responding, echoing and asking connected questions.","expressions":[{"text":"Really? What happened next?","job":"invite someone to continue a story","cloze":"Really? What happened ___?","answer":"next","choices":["next","later","after"]},{"text":"How did you get interested in that?","job":"ask about the origin of an interest","cloze":"How did you get ___ in that?","answer":"interested","choices":["interested","interesting","interest"]},{"text":"What was that like?","job":"ask about an experience","cloze":"What was that ___?","answer":"like","choices":["like","look","feel"]},{"text":"So, you mean that…?","job":"check your understanding","cloze":"So, you ___ that…?","answer":"mean","choices":["mean","means","meaning"]},{"text":"I can relate to that.","job":"connect the speaker’s experience to yours","cloze":"I can ___ to that.","answer":"relate","choices":["relate","relationship","relative"]}],"grammar":{"focus":"Follow-up questions with how, why, when and what happened next.","items":[{"q":"Choose the correct follow-up.","options":["How did you get interested in that?","How you got interested in that?","How did you got interested?"],"answer":"How did you get interested in that?","tag":"grammar:past-question"},{"q":"Choose the correct question.","options":["What was that like?","What that was like?","What did that like?"],"answer":"What was that like?","tag":"grammar:be-question"},{"q":"Choose the natural story follow-up.","options":["What happened next?","What next happened did?","What did happened next?"],"answer":"What happened next?","tag":"grammar:past-question"},{"q":"Complete: Why ___ you choose that course?","options":["did","do","were"],"answer":"did","tag":"grammar:auxiliary"},{"q":"Choose the correct time question.","options":["When did you start?","When you did start?","When did you started?"],"answer":"When did you start?","tag":"grammar:past-question"},{"q":"Choose the checking phrase.","options":["So, you mean that the first week was difficult?","So, you means the first week difficult?","So, mean you first week?"],"answer":"So, you mean that the first week was difficult?","tag":"grammar:checking"},{"q":"Choose the best connected question after “I started a new job.”","options":["How did your first week go?","What is your favorite fruit?","Where is the airport?"],"answer":"How did your first week go?","tag":"grammar:cohesion"},{"q":"Complete: I can ___ to that.","options":["relate","related","relating"],"answer":"relate","tag":"grammar:modal"},{"q":"Choose the correct follow-up after a past event.","options":["How did you feel about it?","How do you felt about it?","How did you felt about it?"],"answer":"How did you feel about it?","tag":"grammar:past-question"},{"q":"Choose the best question form.","options":["What made you decide to continue?","What did made you decide continue?","What make you decided?"],"answer":"What made you decide to continue?","tag":"grammar:question-form"}]},"listening":{"title":"Keeping a story going","questions":[{"q":"What new skill is the colleague learning?","options":["Mapping software","Cooking","Driving"],"answer":"Mapping software","tag":"listening:detail"},{"q":"What does the speaker do first to show interest?","options":["Says “Really?” and asks a connected question","Changes the topic","Talks only about themselves"],"answer":"Says “Really?” and asks a connected question","tag":"listening:strategy"},{"q":"Who introduced the colleague to mapping?","options":["A colleague","A family member","A teacher at school"],"answer":"A colleague","tag":"listening:detail"},{"q":"What can mapping help with?","options":["Community projects","Cooking dinner","Learning music"],"answer":"Community projects","tag":"listening:detail"},{"q":"How were the first lessons?","options":["Challenging","Very easy","Boring and useless"],"answer":"Challenging","tag":"listening:detail"},{"q":"Why did she continue?","options":["She enjoyed seeing progress","She was forced to","She wanted to stop immediately"],"answer":"She enjoyed seeing progress","tag":"listening:inference"},{"q":"What does the speaker check?","options":["Whether practice made the difficult beginning easier","Whether she bought a new computer","Whether she changed jobs"],"answer":"Whether practice made the difficult beginning easier","tag":"listening:checking"},{"q":"How does the speaker relate personally?","options":["By mentioning learning a reporting system","By changing to travel","By talking about salary"],"answer":"By mentioning learning a reporting system","tag":"listening:detail"},{"q":"What do all the questions have in common?","options":["They connect to the previous answer","They are unrelated","They are yes/no only"],"answer":"They connect to the previous answer","tag":"listening:inference"},{"q":"What is the main communication skill?","options":["Show interest and ask connected follow-ups","Give a formal presentation","End a conversation quickly"],"answer":"Show interest and ask connected follow-ups","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write a natural reaction to “I started a new course.”","minWords":5},{"prompt":"Write one follow-up beginning “How did…”","minWords":5},{"prompt":"Write one follow-up beginning “What was…”","minWords":5},{"prompt":"Write one checking question beginning “So, you mean…”","minWords":5},{"prompt":"Write one sentence using “I can relate to that.”","minWords":5},{"prompt":"Write two connected follow-up questions about learning a skill.","minWords":12},{"prompt":"Write a 4-line conversation where every question connects to the previous answer.","minWords":25},{"prompt":"Explain the difference between a connected follow-up and a sudden topic change.","minWords":25},{"prompt":"Draft stage: Write a 60–80 word conversation about learning something difficult.","minWords":60},{"prompt":"Final rewrite and transfer: create a six-exchange conversation using at least three target follow-up expressions.","minWords":80}]},"review":{"keywords":"story · reaction · follow-up · checking","mission":"Keep one conversation going for six exchanges using at least three follow-up expressions."}},{"id":"w2l6","number":6,"week":2,"title":"End conversations professionally","outcome":"Close conversations warmly, confirm next steps and leave a positive final impression.","expressions":[{"text":"It was great speaking with you.","job":"signal a warm ending","cloze":"It was great ___ with you.","answer":"speaking","choices":["speaking","speak","spoke"]},{"text":"I should let you get back to…","job":"respect the other person’s time","cloze":"I should let you get ___ to…","answer":"back","choices":["back","return","again"]},{"text":"Let’s stay in touch.","job":"suggest future contact","cloze":"Let’s stay in ___.","answer":"touch","choices":["touch","contacting","talk"]},{"text":"I’ll send you the details.","job":"promise a next action","cloze":"I’ll ___ you the details.","answer":"send","choices":["send","sent","sending"]},{"text":"I look forward to speaking again.","job":"close a professional interaction","cloze":"I look ___ to speaking again.","answer":"forward","choices":["forward","ahead","future"]}],"grammar":{"focus":"Future arrangements with will and present continuous; “look forward to” + -ing.","items":[{"q":"Choose the correct promise.","options":["I’ll send you the details this afternoon.","I send you details tomorrow yesterday.","I’ll sending the details."],"answer":"I’ll send you the details this afternoon.","tag":"grammar:will"},{"q":"Choose the correct arrangement.","options":["I’m meeting the team tomorrow.","I meeting the team tomorrow.","I’m meet the team tomorrow."],"answer":"I’m meeting the team tomorrow.","tag":"grammar:present-continuous"},{"q":"Choose the correct phrase.","options":["I look forward to speaking again.","I look forward to speak again.","I look forward speaking again."],"answer":"I look forward to speaking again.","tag":"grammar:gerund"},{"q":"Complete: It ___ great speaking with you.","options":["was","were","be"],"answer":"was","tag":"grammar:be"},{"q":"Complete: Let’s ___ in touch.","options":["stay","staying","stayed"],"answer":"stay","tag":"grammar:let-us"},{"q":"Choose the polite time signal.","options":["I should let you get back to the workshop.","You need go now.","Stop talking now."],"answer":"I should let you get back to the workshop.","tag":"grammar:appropriacy"},{"q":"Choose the correct next step.","options":["I’ll review it tomorrow.","I’ll reviewed it tomorrow.","I review it tomorrow yesterday."],"answer":"I’ll review it tomorrow.","tag":"grammar:will"},{"q":"Choose the correct future question.","options":["When will you send the link?","When you will send the link?","When will you sent the link?"],"answer":"When will you send the link?","tag":"grammar:future-question"},{"q":"Complete: We’re ___ again on Thursday.","options":["meeting","meet","met"],"answer":"meeting","tag":"grammar:present-continuous"},{"q":"Choose the strongest professional close.","options":["It was great speaking with you. I’ll send the details today.","Bye. Maybe something later.","Okay finished."],"answer":"It was great speaking with you. I’ll send the details today.","tag":"grammar:cohesion"}]},"listening":{"title":"Closing a professional conversation","questions":[{"q":"What signal tells the speaker it may be time to end?","options":["The other person looks toward the next session","The lights turn off","Someone starts eating"],"answer":"The other person looks toward the next session","tag":"listening:inference"},{"q":"What polite time signal does the speaker use?","options":["I should let you get back to the workshop.","You must leave now.","I am bored."],"answer":"I should let you get back to the workshop.","tag":"listening:strategy"},{"q":"How does the other person describe the conversation?","options":["Great speaking with you","Too long and difficult","Not useful"],"answer":"Great speaking with you","tag":"listening:detail"},{"q":"What does the speaker suggest?","options":["Stay in touch","Never speak again","Change the workshop"],"answer":"Stay in touch","tag":"listening:detail"},{"q":"What does the speaker promise to send?","options":["A project link","A new laptop","A job contract"],"answer":"A project link","tag":"listening:detail"},{"q":"When will it be sent?","options":["That afternoon","Next month","The previous day"],"answer":"That afternoon","tag":"listening:detail"},{"q":"When will the other person review it?","options":["The next day","Immediately before receiving it","Next year"],"answer":"The next day","tag":"listening:sequence"},{"q":"Why is the next step useful?","options":["It makes the follow-up clear","It makes the ending longer","It avoids all future contact"],"answer":"It makes the follow-up clear","tag":"listening:inference"},{"q":"What final phrase does the speaker use?","options":["I look forward to speaking again.","Do not contact me.","That is all."],"answer":"I look forward to speaking again.","tag":"listening:detail"},{"q":"What makes the ending professional?","options":["Respecting time, confirming a next step, and closing warmly","Leaving without saying anything","Making several vague promises"],"answer":"Respecting time, confirming a next step, and closing warmly","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write one warm closing sentence.","minWords":5},{"prompt":"Write one sentence that respects the other person’s time.","minWords":5},{"prompt":"Write one next-action promise using “I’ll…”","minWords":5},{"prompt":"Write one future arrangement using present continuous.","minWords":5},{"prompt":"Write one sentence using “I look forward to…” correctly.","minWords":5},{"prompt":"Write a two-line professional closing.","minWords":12},{"prompt":"Write a closing that includes a specific deadline for your next action.","minWords":15},{"prompt":"Rewrite a vague ending (“We should talk sometime”) as a clear professional next step.","minWords":20},{"prompt":"Draft stage: Write a 50–70 word closing to a conversation after a workshop.","minWords":50},{"prompt":"Final rewrite and transfer: write a complete professional ending that includes time signal, warm close, next action, deadline and final sentence.","minWords":75}]},"review":{"keywords":"time signal · warm close · next action · deadline","mission":"Open, maintain and close a complete four-minute conversation."}},{"id":"w3l7","number":7,"week":3,"title":"Describe your work clearly","outcome":"Explain your role, team and responsibilities to someone outside your field.","expressions":[{"text":"My main responsibility is…","job":"name your most important duty","cloze":"My main ___ is…","answer":"responsibility","choices":["responsibility","response","responsible"]},{"text":"I work closely with…","job":"describe collaboration","cloze":"I work ___ with…","answer":"closely","choices":["closely","close","closed"]},{"text":"A typical task involves…","job":"explain a regular activity","cloze":"A typical task ___…","answer":"involves","choices":["involves","involve","involving"]},{"text":"The purpose of my role is to…","job":"explain why your job exists","cloze":"The ___ of my role is to…","answer":"purpose","choices":["purpose","result","position"]},{"text":"In simple terms…","job":"make technical information accessible","cloze":"In ___ terms…","answer":"simple","choices":["simple","simply","small"]}],"grammar":{"focus":"Present simple for regular duties; gerunds after “involves”; clear noun phrases for roles and departments.","items":[{"q":"Choose the correct duty sentence.","options":["My main responsibility is checking quality.","My main responsibility are checking quality.","My main responsible is check quality."],"answer":"My main responsibility is checking quality.","tag":"grammar:be"},{"q":"Choose the correct collaboration sentence.","options":["I work closely with the finance team.","I works closely with finance team.","I close work with the finance team."],"answer":"I work closely with the finance team.","tag":"grammar:present-simple"},{"q":"Choose the correct “involves” pattern.","options":["A typical task involves preparing reports.","A typical task involves prepare reports.","A typical task involve preparing reports."],"answer":"A typical task involves preparing reports.","tag":"grammar:gerund"},{"q":"Complete: The purpose of my role is ___ support customers.","options":["to","for","at"],"answer":"to","tag":"grammar:infinitive"},{"q":"Choose the clearest noun phrase.","options":["the customer support team","support customer the team","the team customer supporting"],"answer":"the customer support team","tag":"grammar:noun-phrase"},{"q":"Choose the correct third-person form.","options":["She manages client requests.","She manage client requests.","She managing client requests."],"answer":"She manages client requests.","tag":"grammar:third-person"},{"q":"Choose the simple explanation.","options":["In simple terms, I help projects stay on schedule.","In terms simple I project schedule.","Simply terms I helping schedule."],"answer":"In simple terms, I help projects stay on schedule.","tag":"grammar:clarity"},{"q":"Complete: I usually ___ progress data every Friday.","options":["collect","collects","collecting"],"answer":"collect","tag":"grammar:present-simple"},{"q":"Choose the correct question about work.","options":["Who do you work closely with?","Who you work closely with?","Who does you work close with?"],"answer":"Who do you work closely with?","tag":"grammar:question-form"},{"q":"Choose the best result sentence.","options":["The result of my work is a clear weekly update.","The result my work are clear update.","My work result clear weekly."],"answer":"The result of my work is a clear weekly update.","tag":"grammar:noun-phrase"}]},"listening":{"title":"My work in simple terms","questions":[{"q":"What does the speaker avoid at the beginning?","options":["Technical language","Simple explanations","Examples"],"answer":"Technical language","tag":"listening:strategy"},{"q":"In simple terms, what does the speaker do?","options":["Helps projects stay organised and on schedule","Repairs computers","Teaches children"],"answer":"Helps projects stay organised and on schedule","tag":"listening:main-idea"},{"q":"What is the main responsibility?","options":["Collect progress information and make clear updates","Design buildings","Hire all staff"],"answer":"Collect progress information and make clear updates","tag":"listening:detail"},{"q":"What does a typical task include first?","options":["Checking what has been completed","Buying equipment","Calling customers"],"answer":"Checking what has been completed","tag":"listening:sequence"},{"q":"What problem does the speaker identify?","options":["Anything that is late","Only spelling mistakes","Personal disagreements"],"answer":"Anything that is late","tag":"listening:detail"},{"q":"Who does the speaker work with?","options":["Field staff, supervisors and finance","Only the manager","Only outside customers"],"answer":"Field staff, supervisors and finance","tag":"listening:detail"},{"q":"Why are several teams involved?","options":["Each group has part of the needed information","The speaker wants more meetings","No one has any information"],"answer":"Each group has part of the needed information","tag":"listening:reason"},{"q":"What is the purpose of the role?","options":["Help managers understand progress and decide next steps","Make reports longer","Avoid project decisions"],"answer":"Help managers understand progress and decide next steps","tag":"listening:purpose"},{"q":"What is the useful result of an update?","options":["Notice problems early and keep work moving","Create more technical vocabulary","Delay decisions"],"answer":"Notice problems early and keep work moving","tag":"listening:inference"},{"q":"What communication principle is demonstrated?","options":["Explain work so an outsider can understand it","Use as much jargon as possible","List job titles without explaining them"],"answer":"Explain work so an outsider can understand it","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write your job or study role in simple terms.","minWords":5},{"prompt":"Write one sentence beginning “My main responsibility is…”","minWords":5},{"prompt":"Write one sentence beginning “I work closely with…”","minWords":5},{"prompt":"Write one sentence beginning “A typical task involves…”","minWords":5},{"prompt":"Write the purpose of your role using “The purpose of my role is to…”","minWords":5},{"prompt":"Explain one technical word from your field in simple English.","minWords":10},{"prompt":"Write 3 sentences about role, task and collaborators.","minWords":20},{"prompt":"Write 40–60 words explaining your work to a 12-year-old.","minWords":40},{"prompt":"Draft stage: Add the result or value of your work to create a 60–80 word explanation.","minWords":60},{"prompt":"Final rewrite and transfer: write an 80–100 word “My work in simple terms” explanation with no unexplained technical words.","minWords":80}]},"review":{"keywords":"role · main task · collaborators · purpose · result","mission":"Give a two-minute “My work in simple terms” explanation."}},{"id":"w3l8","number":8,"week":3,"title":"Routines and current priorities","outcome":"Compare regular responsibilities with what you are working on now.","expressions":[{"text":"I usually spend my mornings…","job":"describe a normal routine","cloze":"I ___ spend my mornings…","answer":"usually","choices":["usually","current","today"]},{"text":"At the moment, I’m working on…","job":"name a current assignment","cloze":"At the ___, I’m working on…","answer":"moment","choices":["moment","minute","time"]},{"text":"Most weeks, I…","job":"describe a frequent pattern","cloze":"___ weeks, I…","answer":"Most","choices":["Most","Much","Many"]},{"text":"This week is different because…","job":"contrast routine and present","cloze":"This ___ is different because…","answer":"week","choices":["week","weeks","weekly"]},{"text":"My top priority today is…","job":"identify the most urgent task","cloze":"My top ___ today is…","answer":"priority","choices":["priority","prior","important"]}],"grammar":{"focus":"Present simple versus present continuous; adverbs of frequency.","items":[{"q":"Choose the routine sentence.","options":["I usually review plans in the morning.","I am usually reviewing plans every morning now.","I usually reviewing plans."],"answer":"I usually review plans in the morning.","tag":"grammar:present-simple"},{"q":"Choose the current-action sentence.","options":["At the moment, I’m preparing a report.","At the moment, I prepare a report every day.","At the moment, I preparing report."],"answer":"At the moment, I’m preparing a report.","tag":"grammar:present-continuous"},{"q":"Complete: Most weeks, I ___ with colleagues.","options":["coordinate","am coordinating","coordinates"],"answer":"coordinate","tag":"grammar:present-simple"},{"q":"Complete: This week, I ___ on a special project.","options":["am working","work every","works"],"answer":"am working","tag":"grammar:present-continuous"},{"q":"Choose the correct adverb position.","options":["I usually check email at 8 a.m.","I check usually email at 8 a.m.","Usually I am check email."],"answer":"I usually check email at 8 a.m.","tag":"grammar:adverb-frequency"},{"q":"Choose the correct negative current action.","options":["I’m not working on that task today.","I don’t working on that task today.","I not am work on that task."],"answer":"I’m not working on that task today.","tag":"grammar:present-continuous"},{"q":"Choose the correct routine question.","options":["What do you usually do in the morning?","What are you usually do morning?","What you usually doing every morning?"],"answer":"What do you usually do in the morning?","tag":"grammar:question-form"},{"q":"Choose the current question.","options":["What are you working on at the moment?","What do you working at moment?","What are you work on?"],"answer":"What are you working on at the moment?","tag":"grammar:question-form"},{"q":"Complete: My top priority today ___ finishing the client update.","options":["is","are","be"],"answer":"is","tag":"grammar:be"},{"q":"Choose the best contrast.","options":["I usually work on reports, but this week I’m preparing a presentation.","I am usually report but week prepare presentation.","Usually I working reports because presentation."],"answer":"I usually work on reports, but this week I’m preparing a presentation.","tag":"grammar:contrast"}]},"listening":{"title":"My normal week and today’s priority","questions":[{"q":"How does the speaker describe most weeks?","options":["Predictable","Completely different every day","Very quiet"],"answer":"Predictable","tag":"listening:main-idea"},{"q":"What does the speaker usually do first?","options":["Check messages and review the day’s plan","Prepare a presentation","Call customers immediately"],"answer":"Check messages and review the day’s plan","tag":"listening:sequence"},{"q":"What happens after that?","options":["Coordinate with colleagues and update the task list","Go home","Start a new job"],"answer":"Coordinate with colleagues and update the task list","tag":"listening:sequence"},{"q":"What is a normal afternoon activity?","options":["Preparing notes or reports","Attending school","Cooking"],"answer":"Preparing notes or reports","tag":"listening:detail"},{"q":"Why is this week different?","options":["There is an important Thursday deadline","The office is closed","The speaker is on holiday"],"answer":"There is an important Thursday deadline","tag":"listening:reason"},{"q":"What is the speaker working on now?","options":["Final details for a client update","A new building","A job interview"],"answer":"Final details for a client update","tag":"listening:detail"},{"q":"What is the speaker waiting for?","options":["Two pieces of information","A new computer","A salary payment"],"answer":"Two pieces of information","tag":"listening:detail"},{"q":"What is today’s top priority?","options":["Finish the update before 4 p.m.","Read every email again","Change the task list"],"answer":"Finish the update before 4 p.m.","tag":"listening:priority"},{"q":"What happens to normal duties?","options":["They receive less time until the deadline is complete","They disappear permanently","They become more important than the deadline"],"answer":"They receive less time until the deadline is complete","tag":"listening:inference"},{"q":"Which grammar contrast is central to the message?","options":["Routine present simple vs current present continuous","Past perfect vs future perfect","Passive voice only"],"answer":"Routine present simple vs current present continuous","tag":"listening:language"}]},"writing":{"tasks":[{"prompt":"Write one normal weekly duty using present simple.","minWords":5},{"prompt":"Write another routine sentence with “usually”.","minWords":5},{"prompt":"Write one current task using present continuous.","minWords":5},{"prompt":"Write one sentence beginning “At the moment…”","minWords":5},{"prompt":"Write today’s top priority.","minWords":5},{"prompt":"Write one contrast sentence beginning “This week is different because…”","minWords":10},{"prompt":"Write 3 sentences: routine, current task and priority.","minWords":20},{"prompt":"Write a short work log with five routine statements and three current-action statements.","minWords":40},{"prompt":"Draft stage: Write 60–80 words comparing a normal week with this week.","minWords":60},{"prompt":"Final rewrite and transfer: write an 80–100 word update titled “My normal work and my current priority.”","minWords":80}]},"review":{"keywords":"routine 1 · routine 2 · current task · priority","mission":"Speak for two minutes about “My normal work and my current priority.”"}},{"id":"w3l9","number":9,"week":3,"title":"Give a useful work update","outcome":"Report progress, completed actions, current work and next steps.","expressions":[{"text":"So far, I’ve completed…","job":"report completed progress","cloze":"So ___, I’ve completed…","answer":"far","choices":["far","long","now"]},{"text":"I’m currently checking…","job":"describe work in progress","cloze":"I’m ___ checking…","answer":"currently","choices":["currently","current","nowly"]},{"text":"The main issue is…","job":"identify a blocker","cloze":"The main ___ is…","answer":"issue","choices":["issue","problematic","thingy"]},{"text":"I expect to finish by…","job":"give a realistic deadline","cloze":"I ___ to finish by…","answer":"expect","choices":["expect","expects","waiting"]},{"text":"My next step is to…","job":"state the immediate action","cloze":"My ___ step is to…","answer":"next","choices":["next","new","later"]}],"grammar":{"focus":"Present perfect for progress; present continuous for current work; future language for next action and deadline.","items":[{"q":"Choose the correct progress sentence.","options":["So far, I’ve completed the first review.","So far, I completed the first review every day.","So far, I am complete first review."],"answer":"So far, I’ve completed the first review.","tag":"grammar:present-perfect"},{"q":"Choose the current-work sentence.","options":["I’m currently checking the final details.","I currently checked final details now.","I’m currently check final details."],"answer":"I’m currently checking the final details.","tag":"grammar:present-continuous"},{"q":"Choose the blocker sentence.","options":["The main issue is one missing document.","The main issue are missing document one.","Main issue one document missing is."],"answer":"The main issue is one missing document.","tag":"grammar:be"},{"q":"Complete: I expect to finish ___ 3 p.m.","options":["by","at until","on"],"answer":"by","tag":"grammar:deadline"},{"q":"Choose the next-step sentence.","options":["My next step is to update the plan.","My next step is updating to the plan.","My next step update plan is."],"answer":"My next step is to update the plan.","tag":"grammar:infinitive"},{"q":"Choose the correct progress question.","options":["What have you completed so far?","What did you completed so far?","What have you complete so far?"],"answer":"What have you completed so far?","tag":"grammar:present-perfect-question"},{"q":"Choose the correct current question.","options":["What are you working on now?","What do you working on now?","What are you work now?"],"answer":"What are you working on now?","tag":"grammar:present-continuous-question"},{"q":"Choose the realistic future sentence.","options":["I expect to receive it today.","I expecting receive it yesterday tomorrow.","I expect receiving it today to."],"answer":"I expect to receive it today.","tag":"grammar:infinitive"},{"q":"Choose the best contrast.","options":["I’ve completed the review, and I’m now checking the final details.","I completed now and checking yesterday.","I’ve complete review but currently checked."],"answer":"I’ve completed the review, and I’m now checking the final details.","tag":"grammar:tense-contrast"},{"q":"Choose the clearest update order.","options":["completed progress → current work → issue → deadline → next step","issue → unrelated story → greeting → hobby","next year → past childhood → current task"],"answer":"completed progress → current work → issue → deadline → next step","tag":"grammar:organisation"}]},"listening":{"title":"A clear work update","questions":[{"q":"What is the purpose of the message?","options":["Give a quick work update","Introduce a new employee","End a workshop conversation"],"answer":"Give a quick work update","tag":"listening:main-idea"},{"q":"What has already been completed?","options":["The first review","The final presentation","The supplier contract"],"answer":"The first review","tag":"listening:progress"},{"q":"How many sections were corrected?","options":["Two","Five","One"],"answer":"Two","tag":"listening:detail"},{"q":"What is happening now?","options":["Checking final details and confirming numbers","Writing a job application","Starting the first review"],"answer":"Checking final details and confirming numbers","tag":"listening:current-work"},{"q":"Who is helping confirm the numbers?","options":["The finance team","A school teacher","The customer’s family"],"answer":"The finance team","tag":"listening:detail"},{"q":"What is the main issue?","options":["One missing supplier document","A broken computer","A missing employee"],"answer":"One missing supplier document","tag":"listening:blocker"},{"q":"What has the speaker done about the issue?","options":["Requested the document","Cancelled the project","Ignored it"],"answer":"Requested the document","tag":"listening:action"},{"q":"When is the full update expected to finish?","options":["By 3 p.m.","Next week","At midnight yesterday"],"answer":"By 3 p.m.","tag":"listening:deadline"},{"q":"What is the next step after receiving the document?","options":["Add it, check the final version, and send the plan","Begin the first review again","Change the client"],"answer":"Add it, check the final version, and send the plan","tag":"listening:sequence"},{"q":"Does the speaker expect the deadline to change?","options":["No","Yes, definitely","The speaker gives no opinion"],"answer":"No","tag":"listening:inference"}]},"writing":{"tasks":[{"prompt":"Write one sentence about something you have completed so far.","minWords":5},{"prompt":"Write one sentence about what you are currently working on.","minWords":5},{"prompt":"Write one sentence identifying a main issue.","minWords":5},{"prompt":"Write one realistic deadline using “I expect to finish by…”","minWords":5},{"prompt":"Write one next step using “My next step is to…”","minWords":5},{"prompt":"Write a two-sentence update: completed progress + current work.","minWords":15},{"prompt":"Add one blocker and what you are doing about it.","minWords":20},{"prompt":"Write a 50–70 word update using all five target expressions.","minWords":50},{"prompt":"Draft stage: Rewrite a vague update (“Things are going okay”) as a specific useful update.","minWords":50},{"prompt":"Final rewrite and transfer: write an 80–110 word professional work update in this order: progress, current work, issue, deadline, next step.","minWords":80}]},"review":{"keywords":"progress · current work · issue · deadline · next step","mission":"Give a 60–90 second work update with completed progress, current work, blocker, deadline and next step."}}],"levelNote":"Adult/professional communicative pathway: supported A2+ practice moving toward functional B1 independence."};

const NAV={student:[['home','⌂','Home'],['progress','◔','Progress']],teacher:[['teacher-home','⌂','Dashboard'],['students','◎','Students'],['classes','▤','Classes'],['weaknesses','△','Weaknesses'],['reports','▦','Reports'],['teacher-leaderboard','★','Leaderboard']]};
let session=null,currentPage='home',activeLessonId='w1l1',currentStep='vocabulary',apiDB=null;
function getDB(){return apiDB||{version:4,users:[],classes:[],profiles:{},attempts:[],completion:{},writing:{},listeningLocks:{}}}
function saveDB(db){apiDB=db}
function $(id){return document.getElementById(id)} function lesson(id=activeLessonId){return COURSE.lessons.find(l=>l.id===id)||COURSE.lessons[0]} function cap(s){return s.charAt(0).toUpperCase()+s.slice(1)}
async function api(path,options={}){const opts={credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})},...options};const res=await fetch(path,opts);let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||'Request failed');return data}
async function refreshState(){apiDB=await api('/api/state');return apiDB}
function init(){$('loginForm').addEventListener('submit',e=>{e.preventDefault();login($('username').value.trim(),$('password').value)});$('logoutBtn').addEventListener('click',logout);$('menuBtn').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'))} document.addEventListener('DOMContentLoaded',init);
async function login(username,password){$('loginError').textContent='';try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username,password})});session=r.user;await refreshState();$('loginScreen').classList.add('hidden');$('app').classList.remove('hidden');$('app').classList.remove('student-mode','teacher-mode');$('app').classList.add(session.role==='student'?'student-mode':'teacher-mode');$('sidebarName').textContent=session.name;$('sidebarRole').textContent=session.role==='teacher'?'Teacher':'Student';$('sidebarAvatar').textContent=session.name[0];currentPage=session.role==='teacher'?'teacher-home':'home';renderNav();renderPage()}catch(e){$('loginError').textContent=e.message||'Username or password is incorrect.'}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}session=null;apiDB=null;$('app').classList.add('hidden');$('loginScreen').classList.remove('hidden');$('password').value=''}
function renderNav(){const items=NAV[session.role],html=items.map(([id,icon,label])=>`<button class="nav-btn ${currentPage===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');if(session.role==='student'){$('sideNav').innerHTML='';$('studentTopNav').innerHTML=html;$('bottomNav').innerHTML=html+`<button class="nav-btn ${currentPage==='profile'?'active':''}" data-page="profile"><span class="nav-icon">○</span>Profile</button>`;$('studentProfileBtn').classList.remove('hidden');$('studentProfileBtn').textContent=session.name[0]}else{$('sideNav').innerHTML=html;$('studentTopNav').innerHTML='';$('bottomNav').innerHTML=html;$('studentProfileBtn').classList.add('hidden')}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.page;document.querySelector('.sidebar').classList.remove('open');renderNav();renderPage()});$('studentProfileBtn').onclick=()=>{currentPage='profile';renderNav();renderPage()}}
function title(e,h){$('pageEyebrow').textContent=e;$('pageTitle').textContent=h} function progress(v){return `<div class="progress"><span style="width:${Math.max(0,Math.min(100,v))}%"></span></div>`} function renderPage(){session.role==='student'?renderStudent():renderTeacher()} function renderStudent(){({home:studentHome,workbook,course:studentCourse,progress:studentProgress,leaderboard:()=>leaderboard(false),profile}[currentPage]||studentHome)()} function renderTeacher(){({'teacher-home':teacherHome,students,classes,weaknesses,reports,'teacher-leaderboard':()=>leaderboard(true)}[currentPage]||teacherHome)()}
function attempts(sid,skill=null,lid=null){return getDB().attempts.filter(a=>a.studentId===sid&&(!skill||a.skill===skill)&&(!lid||a.lessonId===lid))} function mastery(sid,skill){const db=getDB(),base=db.profiles?.[sid]?.base?.[skill]??60,a=attempts(sid,skill);if(!a.length)return base;const best={};a.forEach(x=>best[x.lessonId]=Math.max(best[x.lessonId]||0,x.score));const vals=Object.values(best),avg=Math.round(vals.reduce((p,c)=>p+c,0)/vals.length);return Math.round(base*.35+avg*.65)} function overall(sid){return Math.round(['vocabulary','grammar','listening','writing'].reduce((a,k)=>a+mastery(sid,k),0)/4)} function points(sid){return getDB().profiles?.[sid]?.points||0}
function completionFor(sid,lid){return getDB().completion?.[sid]?.[lid]||[]} function lessonProgress(sid,lid){return Math.round(completionFor(sid,lid).length/5*100)} function completionPct(sid){return Math.round(COURSE.lessons.reduce((n,l)=>n+completionFor(sid,l.id).length,0)/(COURSE.lessons.length*5)*100)} function writingFor(sid,lid){return getDB().writing?.[sid]?.[lid]||''}
function weakest(sid){const r=['vocabulary','grammar','listening','writing'].map(k=>[k,mastery(sid,k)]).sort((a,b)=>a[1]-b[1]),k=r[0][0],tips={vocabulary:'Retrieve useful expressions without looking at the language bank.',grammar:'Build accurate sentences and connectors before you speak.',listening:'Listen for the main idea first, then details and sequence.',writing:'Organise a clear point, reason and example.'};return{key:k,label:cap(k),score:r[0][1],tip:tips[k]}}
function skillCard(n,v,d){return `<div class="card metric-card"><div class="metric-top"><span class="pill">${d}</span><strong>${v}%</strong></div><h4 style="margin:0">${n}</h4>${progress(v)}</div>`} function metric(l,v,s){return `<div class="card metric-card"><span class="pill">${s}</span><strong>${v}</strong><h4 style="margin:0">${l}</h4></div>`}
function studentHome(){const sid=session.id,w=weakest(sid),moduleDone=completionPct(sid)===100,next=COURSE.lessons.find(l=>completionFor(sid,l.id).length<5)||COURSE.lessons[COURSE.lessons.length-1],step=firstOpenStep(sid,next.id),done=completionFor(sid,next.id).length,stepNames={vocabulary:'Vocabulary',listening:'Listening',grammar:'Grammar',writing:'Writing',review:'Review'};title('Fluency First','Home');if(moduleDone){$('content').innerHTML=`<div class="student-home"><section class="next-action-card module-complete-card"><div class="next-action-copy"><span class="pill teal">Module complete</span><p class="student-kicker">Fluency Foundations</p><h1>You finished Module 1.</h1><p>Your practice evidence is ready for your teacher. Review your progress or revisit any completed topic before the live module challenge.</p><div class="student-cta-row"><button class="primary-btn student-primary-cta" id="openProgressBtn">Review progress →</button><button class="ghost-btn" id="viewCourseBtn">View course</button></div></div><div class="next-action-number"><span>✓</span><small>DONE</small></div></section></div>`;$('openProgressBtn').onclick=()=>{currentPage='progress';renderNav();studentProgress()};$('viewCourseBtn').onclick=()=>{currentPage='course';renderNav();studentCourse()};return}$('content').innerHTML=`<div class="student-home"><section class="next-action-card"><div class="next-action-copy"><span class="pill teal">Your next step</span><p class="student-kicker">Topic ${next.number} of ${COURSE.lessons.length}</p><h1>${stepNames[step]}</h1><h2>${next.title}</h2><p>${next.outcome}</p><div class="next-progress"><div><span>${done}/5 steps complete</span><strong>${lessonProgress(sid,next.id)}%</strong></div>${progress(lessonProgress(sid,next.id))}</div><div class="student-cta-row"><button class="primary-btn student-primary-cta" id="continueBtn">Continue ${stepNames[step]} →</button><button class="ghost-btn" id="viewCourseBtn">View course</button></div></div><div class="next-action-number"><span>${next.number}</span><small>TOPIC</small></div></section><section class="student-glance"><div class="glance-card"><span class="glance-icon">◎</span><div><small>Course progress</small><strong>${completionPct(sid)}%</strong><p>${points(sid)} points earned</p></div><button class="text-link" id="openProgressBtn">See progress →</button></div><div class="glance-card quiet"><span class="glance-icon">↗</span><div><small>Teacher focus</small><strong>${w.label}</strong><p>${w.tip}</p></div></div></section></div>`;const open=()=>{activeLessonId=next.id;currentStep=firstOpenStep(sid,next.id);currentPage='workbook';renderNav();workbook()};$('continueBtn').onclick=open;$('viewCourseBtn').onclick=()=>{currentPage='course';renderNav();studentCourse()};$('openProgressBtn').onclick=()=>{currentPage='progress';renderNav();studentProgress()}}
function studentCourse(){const sid=session.id,rawIndex=COURSE.lessons.findIndex(l=>completionFor(sid,l.id).length<5),currentIndex=rawIndex<0?COURSE.lessons.length-1:rawIndex;title('Fluency First','Course');$('content').innerHTML=`<section class="course-shell"><button class="back-link" id="courseHome">← Home</button><div class="course-intro"><div><span class="pill teal">${COURSE.level}</span><h1>${COURSE.moduleTitle}</h1><p>${COURSE.moduleGoal}</p></div><div class="course-overall"><strong>${completionPct(sid)}%</strong><span>Module progress</span>${progress(completionPct(sid))}</div></div><div class="course-path">${COURSE.lessons.map((l,i)=>{const pct=lessonProgress(sid,l.id),complete=pct===100,current=i===currentIndex,available=i<=currentIndex||complete;return `<button class="course-topic ${complete?'complete':''} ${current?'current':''}" data-topic="${available?l.id:''}" ${available?'':'disabled'}><span class="topic-state">${complete?'✓':current?'→':'○'}</span><span class="topic-copy"><small>Topic ${l.number}</small><strong>${l.title}</strong><span>${complete?'Completed':current?`${firstOpenStep(sid,l.id)[0].toUpperCase()+firstOpenStep(sid,l.id).slice(1)} next`:'Upcoming'}</span></span><span class="topic-progress">${pct}%</span></button>`}).join('')}</div></section>`;$('courseHome').onclick=()=>{currentPage='home';renderNav();studentHome()};document.querySelectorAll('[data-topic]').forEach(b=>{if(!b.dataset.topic)return;b.onclick=()=>{activeLessonId=b.dataset.topic;currentStep=firstOpenStep(sid,activeLessonId);currentPage='workbook';renderNav();workbook()}})}
function listeningLocked(lid){return Boolean(getDB().listeningLocks?.[session.id]?.includes(lid))||completionFor(session.id,lid).includes('listening')}
async function loadListeningPrep(l){const box=$('listeningTranscript');if(!box)return;try{const r=await api(`/api/listening/${l.id}/prep`);if(r.locked){await refreshState();renderActivity();return}box.innerHTML=`<p>${escapeHtml(r.script)}</p>`}catch(e){box.innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}
async function lockListeningScript(l){const btn=$('readyForQuestions'),msg=$('listeningGateMessage');if(!btn)return;btn.disabled=true;btn.textContent='Locking script…';try{await api(`/api/listening/${l.id}/lock`,{method:'POST'});await refreshState();renderActivity()}catch(e){btn.disabled=false;btn.textContent='Done reading & listening — start questions';if(msg)msg.innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}
function firstOpenStep(sid,lid){return ['vocabulary','listening','grammar','writing','review'].find(s=>!completionFor(sid,lid).includes(s))||'review'}
function workbook(){const sid=session.id,l=lesson(),steps=['vocabulary','listening','grammar','writing','review'],labels={vocabulary:'Vocabulary',listening:'Listening',grammar:'Grammar',writing:'Writing',review:'Review'},idx=steps.indexOf(currentStep),done=completionFor(sid,l.id);title(`Topic ${l.number}`,labels[currentStep]);$('content').innerHTML=`<section class="learning-shell"><div class="learning-top"><button class="back-link" id="exitWorkbook">← Home</button><button class="text-link" id="openCourseFromWorkbook">Course map</button></div><div class="learning-heading"><div><span class="pill teal">Topic ${l.number}</span><h1>${l.title}</h1><p>${l.outcome}</p></div><div class="step-summary"><small>Activity ${idx+1} of 5</small><strong>${labels[currentStep]}</strong></div></div><nav class="activity-step-nav" aria-label="Topic activities">${steps.map((s,i)=>{const completed=done.includes(s),current=s===currentStep,available=completed||i<=idx;return `<button type="button" class="activity-step-btn ${completed?'done':''} ${current?'active':''}" data-activity-step="${available?s:''}" ${available?'':'disabled'} aria-current="${current?'step':'false'}"><span class="activity-step-state">${completed?'✓':i+1}</span><span class="activity-step-copy"><strong>${labels[s]}</strong><small>${current?'Current':completed?'Completed · open again':'Locked'}</small></span></button>`}).join('')}</nav><div class="step-track compact-track" aria-hidden="true">${steps.map((s,i)=>`<div class="track-step ${done.includes(s)?'done':''} ${s===currentStep?'active':''}"></div>`).join('')}</div><div id="activityPanel" class="activity-card focused-activity"></div><div class="activity-history-nav">${idx>0?`<button type="button" class="ghost-btn" id="previousActivity">← Previous activity</button>`:''}<span>${done.includes(currentStep)?'Completed activity · you can review or retry it.':'Your progress is saved when you complete this activity.'}</span>${idx<steps.length-1&&done.includes(steps[idx+1])?`<button type="button" class="ghost-btn" id="nextCompletedActivity">Next completed activity →</button>`:''}</div></section>`;$('exitWorkbook').onclick=()=>{currentPage='home';renderNav();studentHome()};$('openCourseFromWorkbook').onclick=()=>{currentPage='course';renderNav();studentCourse()};document.querySelectorAll('[data-activity-step]').forEach(b=>{if(!b.dataset.activityStep)return;b.onclick=()=>{currentStep=b.dataset.activityStep;workbook()}});if($('previousActivity'))$('previousActivity').onclick=()=>{currentStep=steps[idx-1];workbook()};if($('nextCompletedActivity'))$('nextCompletedActivity').onclick=()=>{currentStep=steps[idx+1];workbook()};renderActivity()}
function renderActivity(){const p=$('activityPanel'),l=lesson();if(currentStep==='vocabulary')p.innerHTML=vocabActivity(l);if(currentStep==='listening')p.innerHTML=listeningActivity(l);if(currentStep==='grammar')p.innerHTML=grammarActivity(l);if(currentStep==='writing')p.innerHTML=writingActivity(l);if(currentStep==='review')p.innerHTML=reviewActivity(l);wireActivity(l)}
function buildVocabQuestions(l){const e=l.expressions,all=e.map(x=>x.text);return [
{type:'choice',stage:'Recognise',q:`Which expression would you use to ${e[0].job}?`,options:all,answer:e[0].text,tag:'vocabulary:meaning'},
{type:'choice',stage:'Recognise',q:`Which expression would you use to ${e[1].job}?`,options:all,answer:e[1].text,tag:'vocabulary:meaning'},
{type:'choice',stage:'Retrieve',q:`Complete from memory: ${e[2].cloze}`,options:e[2].choices,answer:e[2].answer,tag:'vocabulary:retrieval'},
{type:'choice',stage:'Retrieve',q:`Complete from memory: ${e[3].cloze}`,options:e[3].choices,answer:e[3].answer,tag:'vocabulary:retrieval'},
{type:'choice',stage:'Retrieve',q:`Complete from memory: ${e[4].cloze}`,options:e[4].choices,answer:e[4].answer,tag:'vocabulary:retrieval'},
{type:'choice',stage:'Apply',q:`In the ${l.title.toLowerCase()} mission, you need to ${e[2].job}. Which expression fits best?`,options:all,answer:e[2].text,tag:'vocabulary:context'},
{type:'choice',stage:'Apply',q:`A partner needs language to ${e[3].job}. What should they say?`,options:all,answer:e[3].text,tag:'vocabulary:context'},
{type:'exact',stage:'Repair',q:`Repair the phrase by typing the missing word: ${e[0].cloze}`,answer:e[0].answer,min:1,tag:'vocabulary:repair'},
{type:'open',stage:'Personalise',q:`Write one true sentence about your own life or work using “${e[1].text}”`,min:6,tag:'vocabulary:personalisation'},
{type:'open',stage:'Produce',q:`Without looking back, write three useful expressions from this topic that you could use in this live mission: ${l.review.mission}`,min:10,tag:'vocabulary:independent-retrieval'}]}
function stageBadge(label){return `<span class="stage-badge">${label}</span>`}
function openEvidence(name,q,min,tag,exact=''){return `<div class="open-evidence"><textarea name="${name}" data-open="1" data-min="${min}" data-tag="${escapeAttr(tag||'')}" ${exact?`data-exact="${escapeAttr(exact)}"`:''} placeholder="Type your answer…"></textarea><small class="muted">${exact?'Type the missing/corrected language.':`Write at least ${min} words.`}</small></div>`}
function spiralReview(l){const idx=COURSE.lessons.findIndex(x=>x.id===l.id);if(idx===0)return `<div class="spiral-card"><strong>First-topic retrieval</strong><p>Close the language bank. Recall three expressions from today, then say one true sentence with each.</p></div>`;const prev=COURSE.lessons[idx-1],older=COURSE.lessons[Math.max(0,idx-3)];const pExp=prev.expressions[0],oExp=older.expressions[1];return `<div class="spiral-grid"><div class="spiral-card"><span class="stage-badge">20% · Previous topic</span><strong>${prev.title}</strong><p>Recall the expression used to ${pExp.job}. Then use it in one new sentence.</p><details><summary>Check expression</summary><p>${pExp.text}</p></details></div><div class="spiral-card"><span class="stage-badge">10% · Older topic</span><strong>${older.title}</strong><p>Recall one expression for this communication job: ${oExp.job}.</p><details><summary>Check expression</summary><p>${oExp.text}</p></details></div><div class="spiral-card"><span class="stage-badge">Transfer</span><strong>Combine old + new</strong><p>Use one expression from an earlier topic and one from today in a two-sentence response.</p></div></div>`}
function moduleChallengeHtml(){return `<section class="module-challenge section"><p class="eyebrow">Module 1 · Integrated challenge</p><h3>One complete professional interaction</h3><p class="muted">Show that the nine topics work together. Do not read a full script.</p><div class="challenge-flow"><label><input type="checkbox" data-challenge> <span><strong>1. Listen & note</strong><small>Replay the work-update audio. Write only five keywords.</small></span></label><label><input type="checkbox" data-challenge> <span><strong>2. Retrieve language</strong><small>Recall six expressions from at least four different topics without opening the language banks.</small></span></label><label><input type="checkbox" data-challenge> <span><strong>3. Prepare in writing</strong><small>Use your Topic 9 final writing as notes: role, responsibility, current priority, progress, issue, next step.</small></span></label><label><input type="checkbox" data-challenge> <span><strong>4. Perform for 3 minutes</strong><small>Meet a new professional, introduce yourself, explain your work, give a current update, ask/answer one follow-up, and close professionally.</small></span></label><label><input type="checkbox" data-challenge> <span><strong>5. Keep · Repair · Upgrade · Retry</strong><small>Teacher gives one correction and one stronger expression. Repeat the weakest 60 seconds.</small></span></label></div><div class="teacher-note"><strong>Success evidence:</strong> message is understandable; at least 6 target expressions; suitable grammar for the situation; connected ideas; one clarification/follow-up strategy; professional close.</div></section>`}
function guidedChunks(chunks){const total=chunks.reduce((n,c)=>n+c.items.length,0);return `<div class="guided-intro"><div><strong>One short step at a time</strong><span>Work through four small sections. Only one question is shown at a time.</span></div><span class="pill teal">${total} tasks</span></div><div class="guided-overview" aria-label="Activity sections">${chunks.map((c,i)=>`<span class="guided-overview-step"><b>${i+1}</b><em>${c.label}</em></span>`).join('')}</div><div class="guided-chunks">${chunks.map((c,i)=>`<details class="guided-chunk" data-guided-chunk ${i===0?'open':''}><summary><span class="chunk-summary-main"><small>Section ${i+1} of ${chunks.length}</small><strong>${c.label}</strong><span>${c.description}</span></span><span class="chunk-summary-count">${c.items.length} task${c.items.length===1?'':'s'}</span></summary><div class="chunk-body"><div class="chunk-task-rail" data-question-rail>${c.items.join('')}</div><div class="guided-nav"><button class="ghost-btn" type="button" data-guided-prev>← Previous</button><span data-guided-count>Question 1 of ${c.items.length}</span><button class="secondary-btn" type="button" data-guided-next>Next question →</button></div></div></details>`).join('')}</div>`}
function wireMcqCards(root=document){root.querySelectorAll('.mcq-picker').forEach(picker=>{if(picker.dataset.wired==='1')return;picker.dataset.wired='1';const slot=picker.querySelector('[data-mcq-slot]'),slotText=picker.querySelector('[data-mcq-slot-text]'),cards=[...picker.querySelectorAll('[data-mcq-option]')],inputs=[...picker.querySelectorAll('[data-mcq-input]')];if(!slot||!slotText||!cards.length)return;const animateToSlot=card=>{const from=card.getBoundingClientRect(),to=slot.getBoundingClientRect(),ghost=document.createElement('div');ghost.className='mcq-fly-card';ghost.textContent=card.dataset.value||card.textContent.trim();ghost.style.left=from.left+'px';ghost.style.top=from.top+'px';ghost.style.width=from.width+'px';ghost.style.height=from.height+'px';document.body.appendChild(ghost);requestAnimationFrame(()=>{ghost.style.transform=`translate(${to.left+to.width/2-(from.left+from.width/2)}px,${to.top+to.height/2-(from.top+from.height/2)}px) scale(.78)`;ghost.style.opacity='.15'});setTimeout(()=>ghost.remove(),280)};const choose=(card,animate=true)=>{const i=Number(card.dataset.mcqOption),input=inputs.find(x=>Number(x.dataset.mcqInput)===i);if(!input)return;inputs.forEach(x=>x.checked=false);cards.forEach(x=>x.classList.remove('selected'));input.checked=true;card.classList.add('selected');slot.classList.add('filled');slotText.textContent=card.dataset.value||card.textContent.trim();if(animate)animateToSlot(card);if(slot.animate)slot.animate([{transform:'scale(.985)'},{transform:'scale(1.02)'},{transform:'scale(1)'}],{duration:240,easing:'ease-out'})};cards.forEach(card=>{card.onclick=()=>choose(card,true);card.ondragstart=e=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',card.dataset.mcqOption);card.classList.add('dragging')};card.ondragend=()=>card.classList.remove('dragging')});slot.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';slot.classList.add('drag-over')};slot.ondragleave=()=>slot.classList.remove('drag-over');slot.ondrop=e=>{e.preventDefault();slot.classList.remove('drag-over');const i=Number(e.dataTransfer.getData('text/plain')),card=cards.find(x=>Number(x.dataset.mcqOption)===i);if(card)choose(card,false)};slot.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&cards.length){e.preventDefault();const selected=cards.findIndex(x=>x.classList.contains('selected')),next=cards[(selected+1)%cards.length];choose(next,true)}}})}

function wireGuidedActivity(){const chunks=[...document.querySelectorAll('[data-guided-chunk]')];chunks.forEach((chunk,chunkIndex)=>{const rail=chunk.querySelector('[data-question-rail]'),cards=rail?[...rail.children]:[],prev=chunk.querySelector('[data-guided-prev]'),next=chunk.querySelector('[data-guided-next]'),counter=chunk.querySelector('[data-guided-count]');if(!rail||!cards.length||!prev||!next)return;let index=0;const sync=()=>{if(counter)counter.textContent=`Question ${index+1} of ${cards.length}`;prev.disabled=index===0;next.textContent=index===cards.length-1?(chunkIndex===chunks.length-1?'Finish section':'Next section →'):'Next question →'};const move=i=>{index=Math.max(0,Math.min(cards.length-1,i));rail.scrollTo({left:cards[index].offsetLeft-rail.offsetLeft,behavior:'smooth'});sync()};prev.onclick=()=>move(index-1);next.onclick=()=>{if(index<cards.length-1){move(index+1);return}const following=chunks[chunkIndex+1];if(following){following.open=true;chunk.open=false;setTimeout(()=>following.scrollIntoView({behavior:'smooth',block:'start'}),40)}else{const check=$('checkActivity')||$('saveWriting');if(check)check.scrollIntoView({behavior:'smooth',block:'center'})}};chunk.addEventListener('toggle',()=>{if(chunk.open){chunks.forEach(other=>{if(other!==chunk)other.open=false});setTimeout(()=>move(index),0)}});sync()})}
function vocabActivity(l){const qs=buildVocabQuestions(l);const item=(q,i)=>`<article class="guided-question"><div class="question-stage">${stageBadge(q.stage)}<span>${i+1}/10</span></div><p>${q.q}</p>${q.type==='choice'?radio('v'+i,q.options,q.answer,q.tag):openEvidence('v'+i,q.q,q.min,q.tag,q.type==='exact'?q.answer:'')}</article>`;const chunks=[{label:'Recognise',description:'Connect meaning to the useful expressions.',items:qs.slice(0,2).map((q,i)=>item(q,i))},{label:'Remember',description:'Retrieve the language from memory.',items:qs.slice(2,5).map((q,i)=>item(q,i+2))},{label:'Apply',description:'Choose and repair language in context.',items:qs.slice(5,8).map((q,i)=>item(q,i+5))},{label:'Produce',description:'Use the language for your own meaning.',items:qs.slice(8,10).map((q,i)=>item(q,i+8))}];return `<p class="eyebrow">Skill 1 · Vocabulary · Topic ${l.number}</p><div class="activity-title-row"><div><h3>${l.title}: useful language</h3><p class="muted">Recognise → remember → apply → produce.</p></div><span class="pill gold">A2+ → B1</span></div>${guidedChunks(chunks)}<div id="activityFeedback"></div><button class="primary-btn guided-submit" id="checkActivity">Check my vocabulary</button>`}
function listeningActivity(l){const locked=listeningLocked(l.id);if(!locked)return `<p class="eyebrow">Skill 2 · Listening · Topic ${l.number}</p><div class="activity-title-row"><div><h3>${l.listening.title}</h3><p class="muted">Stage 1 · Read and listen before you see any questions.</p></div><span class="pill audio-pill">Script + audio</span></div><div class="prelisten-box"><strong>How this works</strong><p>Read the script while you listen. Replay the audio as many times as you need. When you are ready, press the button below. The script will then lock and the questions will open.</p></div><div class="card transcript-card"><div class="section-head"><div><span class="pill teal">Reading script</span><h3>Follow the message</h3></div><span class="pill">Visible now</span></div><div id="listeningTranscript" class="listening-transcript" style="font-size:1.04rem;line-height:1.8"><p class="muted">Loading script…</p></div></div><div class="audio-box section"><button id="playAudio" class="play-btn">▶</button><div><strong>Play listening</strong><div id="audioStatus" class="muted">Listen while reading. Replay as many times as you need.</div></div></div><div class="teacher-note section"><strong>Ready for the questions?</strong><p>After you continue, this script will be locked for this topic. You will still be able to replay the audio as many times as you want.</p><button class="primary-btn" id="readyForQuestions">Done reading & listening — start questions</button><div id="listeningGateMessage"></div></div>`;const auto=l.listening.questions.slice(0,8);const autoItem=(q,i)=>`<article class="guided-question"><div class="question-stage">${stageBadge(i<2?'Gist':i<6?'Detail':'Inference')}<span>${i+1}/10</span></div><p>${q.q}</p>${radio('l'+i,q.options,q.answer,q.tag)}</article>`;const keywords=`<article class="guided-question"><div class="question-stage">${stageBadge('Keywords')}<span>9/10</span></div><p>Write 3–5 keywords that carry the most important meaning in this listening.</p>${openEvidence('l8','keywords',3,'listening:note-taking')}</article>`;const reconstruct=`<article class="guided-question"><div class="question-stage">${stageBadge('Reconstruct')}<span>10/10</span></div><p>In one or two sentences, reconstruct the speaker’s main message for the topic “${l.title}”.</p>${openEvidence('l9','reconstruct',10,'listening:reconstruction')}</article>`;const chunks=[{label:'Understand',description:'Catch the overall message first.',items:auto.slice(0,2).map((q,i)=>autoItem(q,i))},{label:'Listen closely',description:'Find important details.',items:auto.slice(2,6).map((q,i)=>autoItem(q,i+2))},{label:'Think',description:'Work out meaning and intention.',items:auto.slice(6,8).map((q,i)=>autoItem(q,i+6))},{label:'Rebuild',description:'Capture and reconstruct the message.',items:[keywords,reconstruct]}];return `<p class="eyebrow">Skill 2 · Listening · Topic ${l.number}</p><div class="activity-title-row"><div><h3>${l.listening.title}</h3><p class="muted">Stage 2 · The script is locked. Work through one short listening section at a time.</p></div><span class="pill gold">Script locked</span></div><div class="teacher-note"><strong>🔒 Reading script locked</strong><span>Audio remains available without a replay limit.</span></div><div class="audio-box section"><button id="playAudio" class="play-btn">▶</button><div><strong>Replay listening</strong><div id="audioStatus" class="muted">Play as many times as you need while answering.</div></div></div>${guidedChunks(chunks)}<div id="activityFeedback"></div><button class="primary-btn guided-submit" id="checkActivity">Check my listening</button>`}
function grammarActivity(l){const auto=l.grammar.items.slice(0,8);const autoItem=(q,i)=>`<article class="guided-question"><div class="question-stage">${stageBadge(i<3?'Notice':i<6?'Control':'Apply')}<span>${i+1}/10</span></div><p>${q.q}</p>${radio('g'+i,q.options,q.answer,q.tag)}</article>`;const personal=`<article class="guided-question"><div class="question-stage">${stageBadge('Personalise')}<span>9/10</span></div><p>Write one true sentence about your own work, study or life using today’s grammar for “${l.title}”.</p>${openEvidence('g8','personal grammar',8,'grammar:personalisation')}</article>`;const transfer=`<article class="guided-question"><div class="question-stage">${stageBadge('Transfer')}<span>10/10</span></div><p>Write two connected sentences that would help you complete this live mission: ${l.review.mission}</p>${openEvidence('g9','mission grammar',14,'grammar:independent-production')}</article>`;const chunks=[{label:'Notice',description:'Spot the accurate pattern.',items:auto.slice(0,3).map((q,i)=>autoItem(q,i))},{label:'Control',description:'Build the form accurately.',items:auto.slice(3,6).map((q,i)=>autoItem(q,i+3))},{label:'Apply',description:'Use the grammar in meaningful context.',items:auto.slice(6,8).map((q,i)=>autoItem(q,i+6))},{label:'Produce',description:'Make the grammar yours.',items:[personal,transfer]}];return `<p class="eyebrow">Skill 3 · Grammar · Topic ${l.number}</p><div class="activity-title-row"><div><h3>Grammar for the mission</h3><p class="muted">${l.grammar.focus}</p></div><span class="pill gold">Notice → control → use</span></div><div class="boost-entry"><div><span class="boost-kicker">EnglishGate Boost</span><strong>Boost starts after your attempt</strong><p>Check the grammar first. Boost will collect only the checked questions you miss, teach the pattern briefly, then retest you.</p></div><button class="boost-launch-btn" id="boostActivity">Boost missed grammar</button></div>${guidedChunks(chunks)}<div id="activityFeedback"></div><button class="primary-btn guided-submit" id="checkActivity">Check my grammar</button>`}

function boostHint(q){const tag=String(q.tag||'');const rules=[
['question','Look at the word order. English questions often need a helping verb before the subject.'],
['infinitive','After language about a goal or something you want to do, look for “to + base verb”.'],
['present-simple','Check the subject first, then choose the present-simple form that agrees with it.'],
['negative','A present-simple negative normally uses do/does + not + the base verb.'],
['connector-because','Use “because” when the second idea gives a reason.'],
['connector-but','Use “but” when the second idea contrasts with the first.'],
['connector-so','Use “so” when the second idea is a result.'],
['connector','Decide whether the ideas show addition, contrast, reason or result.'],
['gerund','After “responsible for”, the next verb normally uses the -ing form.'],
['be','Check whether the subject needs am, is or are.'],
['collocation','Use the fixed phrase from the lesson rather than translating word by word.'],
['time-phrase','Check which preposition naturally introduces the time expression.'],
['complete-sentence','Look for a complete subject + verb + idea.'],
['do','Check the subject before choosing do or does.']
];const hit=rules.find(([key])=>tag.includes(key));return hit?hit[1]:'Compare the choices with the model language from this topic. Read the whole sentence, not just one word.'}
function boostRecovery(l){const core=[...attempts(session.id,'grammar',l.id)].reverse().find(a=>!(a.tags||[]).some(t=>String(t).startsWith('boost:')));if(!core)return{ready:false,reason:'Try and check the grammar activity first.',missed:[]};const tags=core.tags||[],missed=[...new Set(tags.filter(t=>/^missq:[0-7]$/.test(String(t))).map(t=>Number(String(t).split(':')[1])))].sort((a,b)=>a-b),diagnosed=tags.includes('diagnostic:no-misses')||missed.length>0;if(!diagnosed)return{ready:false,reason:'Check the grammar activity once more so EnglishGate can identify the exact questions you miss.',missed:[]};if(!missed.length)return{ready:false,reason:'No Boost is needed. You did not miss any automatically checked grammar questions in your latest attempt.',missed:[]};return{ready:true,reason:'',missed,core}}
function boostFreshQuestion(q){const tag=String(q.tag||'');if(tag.includes('question'))return{q:'Choose the correctly formed question.',options:['Where do they use English?','Where they use English?','Where does they use English?'],answer:'Where do they use English?'};if(tag.includes('third-person'))return{q:'Complete: Amina ___ with international clients every week.',options:['works','work','working'],answer:'works'};if(tag.includes('negative'))return{q:'Choose the correct negative sentence.',options:['He does not need more time.','He not needs more time.','He does not needs more time.'],answer:'He does not need more time.'};if(tag.includes('present-simple'))return{q:'Choose the accurate routine sentence.',options:['I usually practise English after work.','I usually practises English after work.','I am usually practise English after work.'],answer:'I usually practise English after work.'};if(tag.includes('infinitive'))return{q:'Complete: My next goal is ___ lead a larger project.',options:['to','for','at'],answer:'to'};if(tag.includes('gerund'))return{q:'Complete: She is responsible for ___ the weekly schedule.',options:['checking','check','to check'],answer:'checking'};if(tag.includes('because'))return{q:'Choose the best connector: I practise every day ___ I want to speak more confidently.',options:['because','but','so'],answer:'because'};if(tag.includes('but')||tag.includes('contrast'))return{q:'Choose the best connector: I understand the topic, ___ I need more time to answer.',options:['but','because','so'],answer:'but'};if(tag.includes('connector-so'))return{q:'Choose the best connector: I have a presentation tomorrow, ___ I am practising tonight.',options:['so','but','because'],answer:'so'};if(tag.includes('modal'))return{q:'Complete: You ___ ask the speaker to repeat the question.',options:['can','are','have'],answer:'can'};if(tag.includes('present-perfect'))return{q:'Complete: I ___ worked with this team for two years.',options:['have','has','am'],answer:'have'};if(tag.includes('present-continuous'))return{q:'Complete: We ___ preparing the final report now.',options:['are','do','have'],answer:'are'};if(tag.includes('will')||tag.includes('deadline'))return{q:'Complete: I ___ send the final version tomorrow morning.',options:['will','am','have'],answer:'will'};if(tag.includes('be'))return{q:'Complete: My main challenge ___ speaking without long pauses.',options:['is','are','be'],answer:'is'};if(tag.includes('have'))return{q:'Complete: I ___ two main responsibilities in my current role.',options:['have','has','having'],answer:'have'};if(tag.includes('complete-sentence'))return{q:'Choose the complete sentence.',options:['We use English at work.','We English at work.','Use English work.'],answer:'We use English at work.'};return{q:'Fresh practice for the same grammar rule: '+q.q,options:q.options,answer:q.answer}}
function startBoost(l){if(!l.grammar?.items?.length)return;const recovery=boostRecovery(l);if(!recovery.ready){showModal('<div class="boost-modal boost-result"><span class="boost-kicker">EnglishGate Boost</span><h3>Boost is not ready yet</h3><p>'+escapeHtml(recovery.reason)+'</p><button class="primary-btn" id="boostBack">Back to grammar</button></div>');$('boostBack').onclick=closeModal;return}const qs=recovery.missed.map(i=>({index:i,original:l.grammar.items[i],retest:boostFreshQuestion(l.grammar.items[i])})).filter(x=>x.original);renderBoost(l,{questions:qs,index:0,wrong:0,hints:0,totalAttempts:0,mastered:0,unresolved:0,saving:false,feedback:''})}
function renderBoost(l,state){const item=state.questions[state.index],q=item.retest,original=item.original,lesson=boostHint(original);showModal('<div class="boost-modal"><div class="boost-modal-head"><div><span class="boost-kicker">EnglishGate Boost · Targeted recovery</span><h3>Fix what you missed</h3><p>Question '+(state.index+1)+' of '+state.questions.length+' missed grammar skill'+(state.questions.length===1?'':'s')+'.</p></div><button class="icon-btn" data-close>×</button></div><div class="boost-flow"><span class="active">1 · Review</span><span class="active">2 · Retest</span><span>3 · Mastery</span></div><div class="boost-question-card"><div class="boost-original"><small>Workbook question you missed</small><strong>'+escapeHtml(original.q)+'</strong></div><div class="boost-mini"><strong>Mini lesson</strong><span>'+escapeHtml(lesson)+'</span><small>Model answer from the original item: '+escapeHtml(original.answer)+'</small></div><div class="question-stage">'+stageBadge('Fresh retest')+'<span>'+(state.index+1)+'/'+state.questions.length+'</span></div><p class="boost-question">'+escapeHtml(q.q)+'</p>'+radio('boostChoice',q.options,q.answer,original.tag)+(state.wrong?'<div class="boost-hint"><strong>Try once more</strong><span>'+escapeHtml(lesson)+'</span></div>':'')+'<div id="boostFeedback">'+(state.feedback?'<div class="feedback bad">'+escapeHtml(state.feedback)+'</div>':'')+'</div><button class="primary-btn boost-submit" id="boostSubmit">Check retest answer</button></div><p class="boost-note">The retest changes the context so you apply the rule instead of memorising the old answer.</p></div>');document.querySelector('[data-close]').onclick=closeModal;wireMcqCards(document.getElementById('modalRoot')||document);$('boostSubmit').onclick=()=>submitBoost(l,state)}
async function submitBoost(l,state){const selected=document.querySelector('input[name="boostChoice"]:checked');if(!selected){$('boostFeedback').innerHTML='<div class="feedback bad">Choose an answer first.</div>';return}const item=state.questions[state.index];state.totalAttempts++;if(selected.value===item.retest.answer){state.mastered++;state.feedback='';state.wrong=0;state.index++;if(state.index>=state.questions.length){await finishBoost(l,state);return}renderBoost(l,state);return}state.wrong++;state.hints++;if(state.wrong<2){state.feedback='Not yet. Read the mini lesson and try this fresh question once more.';renderBoost(l,state);return}state.unresolved++;state.feedback='';state.wrong=0;state.index++;if(state.index>=state.questions.length){await finishBoost(l,state);return}renderBoost(l,state)}
async function finishBoost(l,state){if(state.saving)return;state.saving=true;const total=state.questions.length,score=Math.round(state.mastered/Math.max(1,total)*100),mastered=state.unresolved===0&&state.mastered===total,tags=['boost:retest','boost:grammar',mastered?'boost:mastered':'boost:needs-practice',...state.questions.slice(0,7).map(x=>'boostq:'+x.index)].slice(0,10);try{await recordAttempt(session.id,l.id,'grammar',score,tags);await refreshState();showModal('<div class="boost-modal boost-result"><div class="boost-result-icon">'+(mastered?'✓':'↻')+'</div><span class="boost-kicker">EnglishGate Boost</span><h3>'+(mastered?'Missed grammar repaired':'Some grammar still needs practice')+'</h3><p>'+(mastered?'You reviewed the rules and answered fresh retest questions successfully. Your original workbook score remains saved separately.':'Your recovery result has been saved. Run Boost again after your next grammar attempt if these skills are still missed.')+'</p><div class="boost-result-grid"><div><small>Original misses</small><strong>'+total+'</strong></div><div><small>Recovered</small><strong>'+state.mastered+'</strong></div><div><small>Boost mastery</small><strong>'+score+'%</strong></div></div><button class="primary-btn" id="boostBack">Back to grammar</button></div>');$('boostBack').onclick=()=>{closeModal();renderActivity()}}catch(e){state.saving=false;state.feedback='Could not save Boost progress: '+e.message;renderBoost(l,state)}}
function writingResponses(sid,lid){const raw=writingFor(sid,lid);if(!raw)return [];try{const parsed=JSON.parse(raw);return Array.isArray(parsed)?parsed:[]}catch{return [raw]}}
function writingActivity(l){const saved=writingResponses(session.id,l.id),stages=['Sentence','Sentence','Repair','Extend','Extend','Connect','Guided','Guided','Draft','Final transfer'];const item=(t,i)=>`<article class="guided-question writing-guided-question"><div class="writing-task-head"><div>${stageBadge(stages[i])}<strong>${i+1}. ${t.prompt}</strong></div><span>${t.minWords}+ words</span></div><textarea class="writing-response" data-writing="${i}" data-min="${t.minWords}" placeholder="Write your answer here…">${escapeHtml(saved[i]||'')}</textarea><div class="word-count" data-count="${i}">0 words</div></article>`;const chunks=[{label:'Build',description:'Create clear sentences and repair weak language.',items:l.writing.tasks.slice(0,3).map((t,i)=>item(t,i))},{label:'Extend',description:'Add detail and connect your ideas.',items:l.writing.tasks.slice(3,6).map((t,i)=>item(t,i+3))},{label:'Draft',description:'Develop your response with guided support.',items:l.writing.tasks.slice(6,9).map((t,i)=>item(t,i+6))},{label:'Publish',description:'Rewrite independently and make it stronger.',items:[item(l.writing.tasks[9],9)]}];return `<p class="eyebrow">Skill 4 · Writing · Topic ${l.number}</p><div class="activity-title-row"><div><h3>Build the writing step by step</h3><p class="muted">Build → extend → draft → publish.</p></div><span class="pill gold">A2+ → B1</span></div>${guidedChunks(chunks)}<div class="teacher-note section"><strong>Before the final transfer:</strong> reread your draft, correct one accuracy problem, replace one weak word or expression, and make the organisation clearer. Your final response should be stronger, not simply longer.</div><div id="activityFeedback"></div><button class="primary-btn guided-submit" id="saveWriting">Save my writing</button>`}
function reviewActivity(l){const w=weakest(session.id);return `<p class="eyebrow">Step 5 · Retrieval, transfer & live-class preparation</p><h3>Do not finish the topic and forget it.</h3><p class="muted">About 70% of your attention stays on today’s topic; the review deliberately pulls language back from earlier topics.</p><div class="grid grid-2"><div class="card"><span class="pill teal">Current focus</span><h3>${w.label} · ${w.score}%</h3><p>${w.tip}</p>${progress(w.score)}</div><div class="card"><span class="pill gold">Today’s speaking mission</span><h3>${l.review.mission}</h3><p>Planning keywords: <strong>${l.review.keywords}</strong></p></div></div><section class="section"><div class="section-head"><div><h3>Spiral retrieval</h3><p>Previous language returns before the live lesson.</p></div><span class="pill">70 / 20 / 10</span></div>${spiralReview(l)}</section><div class="recommendation section"><p class="eyebrow">Transfer rule</p><h3>Prepare with keywords, not a memorised script.</h3><p>Use the workbook to prepare accuracy. Use the live class to speak, receive one focused correction, and immediately retry.</p></div>${l.number===9?moduleChallengeHtml():''}<div id="activityFeedback"></div><button class="primary-btn section" id="finishReview">${l.number===9?'Complete Module 1 challenge preparation':'Mark topic ready for live class'}</button>`}
function radio(name,options,answer,tag=''){return `<div class="mcq-picker" data-mcq="${escapeAttr(name)}"><div class="mcq-answer-slot" data-mcq-slot tabindex="0" aria-label="Selected answer"><span class="mcq-slot-label">Your answer</span><strong data-mcq-slot-text>Choose one option below</strong><small>Tap a card or drag it here</small></div><div class="mcq-option-cards">${options.map((o,i)=>`<button class="mcq-option-card" type="button" draggable="true" data-mcq-option="${i}" data-value="${escapeAttr(o)}"><span class="mcq-option-index">${String.fromCharCode(65+i)}</span><span class="mcq-option-text">${escapeHtml(o)}</span></button><input class="mcq-native-input" type="radio" name="${name}" value="${escapeAttr(o)}" data-answer="${escapeAttr(answer)}" data-tag="${escapeAttr(tag)}" data-mcq-input="${i}" tabindex="-1" aria-hidden="true">`).join('')}</div></div>`}
const audioCache={};
async function playListening(l){const btn=$('playAudio'),status=$('audioStatus');if(!btn)return;try{btn.disabled=true;btn.textContent='…';status.textContent='Loading natural voice…';let url=audioCache[l.id];if(!url){const res=await fetch(`/api/audio/${l.id}`,{credentials:'include'});if(!res.ok){let msg='Natural audio is unavailable.';try{const d=await res.json();msg=d.error||msg}catch{}throw new Error(msg)}const blob=await res.blob();url=URL.createObjectURL(blob);audioCache[l.id]=url}const audio=new Audio(url);status.textContent='Playing · listen without reading a transcript';btn.textContent='❚❚';audio.onended=()=>{btn.disabled=false;btn.textContent='▶';status.textContent='Finished. Replay for detail when you are ready.'};audio.onerror=()=>{btn.disabled=false;btn.textContent='▶';status.textContent='Audio playback failed.'};await audio.play()}catch(e){btn.disabled=false;btn.textContent='▶';status.textContent=e.message}}
function wireActivity(l){wireMcqCards();if($('playAudio'))$('playAudio').onclick=()=>playListening(l);if($('listeningTranscript'))loadListeningPrep(l);if($('readyForQuestions'))$('readyForQuestions').onclick=()=>lockListeningScript(l);if($('boostActivity'))$('boostActivity').onclick=()=>startBoost(l);if($('checkActivity'))$('checkActivity').onclick=checkCurrent;wireGuidedActivity();document.querySelectorAll('.writing-response').forEach(t=>{const update=()=>{const n=t.value.trim()?t.value.trim().split(/\s+/).length:0;const c=document.querySelector(`[data-count="${t.dataset.writing}"]`);if(c)c.textContent=`${n} words · minimum ${t.dataset.min}`};t.oninput=update;update()});if($('saveWriting'))$('saveWriting').onclick=()=>saveWriting(l);if($('finishReview'))$('finishReview').onclick=async()=>{if(l.number===9){const boxes=[...document.querySelectorAll('[data-challenge]')];if(boxes.length&&boxes.some(x=>!x.checked)){const f=$('activityFeedback');if(f)f.innerHTML='<div class="feedback bad">Complete all five Module 1 challenge preparation checks before marking the module ready.</div>';return}}await markDone(session.id,l.id,'review');await refreshState();currentPage='home';renderNav();studentHome()}}
async function saveWriting(l){const boxes=[...document.querySelectorAll('.writing-response')],responses=boxes.map(t=>t.value.trim()),f=$('activityFeedback');let met=0;boxes.forEach(t=>{const n=t.value.trim()?t.value.trim().split(/\s+/).length:0;if(n>=Number(t.dataset.min))met++});if(met<10){f.innerHTML=`<div class="feedback bad">Complete all 10 writing tasks to the minimum length. You have completed ${met}/10.</div>`;return}const score=Math.round(met/10*100);try{await api(`/api/writing/${l.id}`,{method:'PUT',body:JSON.stringify({content:JSON.stringify(responses),score})});await refreshState();currentStep=firstOpenStep(session.id,activeLessonId);f.innerHTML='<div class="feedback good">Writing saved. Your next step is ready.</div>';setTimeout(workbook,650)}catch(e){f.innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}
async function checkCurrent(){let total=10,correct=0,tags=[],grammarMissed=[];const countOpen=()=>{document.querySelectorAll('[data-open="1"]').forEach(el=>{const value=el.value.trim(),exact=el.dataset.exact||'',min=Number(el.dataset.min||1);let ok=false;if(exact)ok=value.toLowerCase().replace(/[.?!]/g,'').trim()===exact.toLowerCase().replace(/[.?!]/g,'').trim();else ok=(value?value.split(/\s+/).length:0)>=min;if(ok)correct++;if(el.dataset.tag)tags.push(el.dataset.tag)})};const groups=[...new Set([...document.querySelectorAll('input[type=radio]')].map(x=>x.name))];groups.forEach(g=>{const c=document.querySelector(`input[name="${g}"]:checked`),isGrammarAuto=currentStep==='grammar'&&/^g[0-7]$/.test(g);if(c&&c.value===c.dataset.answer)correct++;else if(isGrammarAuto)grammarMissed.push(Number(g.slice(1)));if(c&&c.dataset.tag)tags.push(c.dataset.tag)});countOpen();if(currentStep==='grammar')tags=grammarMissed.length?grammarMissed.map(i=>`missq:${i}`):['diagnostic:no-misses'];const score=Math.round(correct/total*100);$('activityFeedback').innerHTML=`<div class="feedback ${score>=70?'good':'bad'}">${correct}/${total} evidence points · ${score}%. ${currentStep==='grammar'&&grammarMissed.length?`Boost is ready for ${grammarMissed.length} checked question${grammarMissed.length===1?'':'s'} you missed.`:score>=70?'Good work. Recognition and production evidence have been saved.':'Complete the unanswered production tasks and review the topic language before retrying.'}</div>`;try{await recordAttempt(session.id,activeLessonId,currentStep,score,tags);if(score>=70)await markDone(session.id,activeLessonId,currentStep);await refreshState();if(score>=70&&!(currentStep==='grammar'&&grammarMissed.length)){currentStep=firstOpenStep(session.id,activeLessonId);setTimeout(workbook,900)}}catch(e){$('activityFeedback').innerHTML=`<div class="feedback bad">Could not save progress: ${escapeHtml(e.message)}</div>`}}
async function recordAttempt(studentId,lessonId,skill,score,tags=[]){await api('/api/attempts',{method:'POST',body:JSON.stringify({lessonId,skill,score,tags:[...new Set(tags)]})})}
async function markDone(studentId,lid,step){await api('/api/completion',{method:'POST',body:JSON.stringify({lessonId:lid,step})})}
function studentProgress(){const sid=session.id,w=weakest(sid),ats=attempts(sid).slice(-5).reverse();title('Fluency First','Progress');$('content').innerHTML=`<section class="progress-shell"><div class="progress-hero-card"><div><span class="pill teal">Module 1</span><h1>${completionPct(sid)}% complete</h1><p>Keep moving one topic at a time. Your teacher uses these results to decide what needs revision in the live class.</p></div><button class="ghost-btn" id="progressCourseBtn">View course map</button></div><div class="student-skill-grid">${['vocabulary','grammar','listening','writing'].map(k=>skillCard(cap(k),mastery(sid,k),mastery(sid,k)>=75?'On track':'Keep practising')).join('')}</div><section class="section student-progress-grid"><div class="card"><span class="pill gold">Recommended review</span><h3>${w.label} · ${w.score}%</h3><p>${w.tip}</p>${progress(w.score)}</div><div class="card"><span class="pill">Motivation</span><h3>${points(sid)} points</h3><p>Points reward completed practice and successful retries.</p><button class="text-link" id="openLeaderboardBtn">View leaderboard →</button></div></section><section class="section card"><div class="section-head"><div><h3>Recent practice</h3><p>Your latest five pieces of learning evidence.</p></div></div>${ats.length?ats.map(a=>`<div class="attempt-row"><div><strong>${lesson(a.lessonId).title} · ${cap(a.skill)}</strong><span>${new Date(a.at).toLocaleDateString()}</span></div><strong>${a.score}%</strong></div>`).join(''):'<p class="muted">Complete an activity to start your evidence history.</p>'}</section></section>`;$('progressCourseBtn').onclick=()=>{currentPage='course';renderNav();studentCourse()};$('openLeaderboardBtn').onclick=()=>{currentPage='leaderboard';renderNav();leaderboard(false)}}
function profile(){const u=getDB().users.find(x=>x.id===session.id)||session;title('Fluency First','Profile');$('content').innerHTML=`<section class="profile-shell"><div class="card profile-card"><div class="profile-avatar-large">${escapeHtml(u.name[0])}</div><h2>${escapeHtml(u.name)}</h2><p class="muted">${COURSE.level} · ${COURSE.moduleTitle}</p><div class="profile-row"><span>Username</span><strong>${escapeHtml(u.username)}</strong></div><div class="profile-row"><span>Teacher</span><strong>Teacher Ahmed</strong></div><button class="ghost-btn" id="resetHelp">Password help</button><button class="ghost-btn danger-action" id="studentLogout">Sign out</button></div></section>`;$('resetHelp').onclick=()=>alert('Ask your teacher to reset your password.');$('studentLogout').onclick=logout}
function classStudents(){return getDB().users.filter(u=>u.role==='student'&&u.classIds?.includes('c1'))}
function teacherHome(){const sts=classStudents(),avgComp=Math.round(sts.reduce((a,s)=>a+completionPct(s.id),0)/sts.length),priority=sts.filter(s=>weakest(s.id).score<65),cw=aggregateWeaknesses()[0];title('Teacher dashboard','Class overview');$('content').innerHTML=`<section class="hero"><div><p class="eyebrow">Fluency Foundations</p><h1>Teach what the evidence says matters.</h1><p>Workbook practice happens outside class. Your dashboard turns attempts into revision priorities for the next live speaking lesson.</p></div><div class="hero-action"><small>Next class recommendation</small><strong>${cw?.label||'Collect more evidence'}</strong><button class="secondary-btn" id="openWeak">View weakness map →</button></div></section><section class="section grid grid-4">${metric('Students',sts.length,'Enrolled')}${metric('Active',sts.filter(s=>attempts(s.id).length>0).length,'Has practice evidence')}${metric('Completion',avgComp+'%','Module 1 average')}${metric('Need support',priority.length,'Below 65% in one skill')}</section><section class="section grid grid-2"><div class="card"><h3>Needs your attention</h3>${priority.length?priority.map(s=>`<div class="weakness"><strong>${s.name} · ${weakest(s.id).label} ${weakest(s.id).score}%</strong><span>${weakest(s.id).tip}</span></div>`).join(''):'<p class="muted">No students are currently below the support threshold.</p>'}</div><div class="recommendation"><p class="eyebrow">Recommended revision</p><h3>${cw?.label||'Collect more practice data'}</h3><p>${cw?`${cw.count} student${cw.count!==1?'s':''} currently need this area most. Open the weakness map before your next live class.`:'Ask students to complete Week 1 practice so the dashboard can identify a class pattern.'}</p><button class="secondary-btn" id="openStudents">See students</button></div></section>`;$('openWeak').onclick=()=>{currentPage='weaknesses';renderNav();weaknesses()};$('openStudents').onclick=()=>{currentPage='students';renderNav();students()}}
function students(){const sts=classStudents();title('Class management','Students');$('content').innerHTML=`<div class="section-head"><div><h3>Fluency Foundations</h3><p>Create student access and review progress evidence.</p></div><button class="primary-btn" id="addStudent">+ Add student</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Completion</th><th>Vocabulary</th><th>Grammar</th><th>Listening</th><th>Writing</th><th>Focus</th><th></th></tr></thead><tbody>${sts.map(s=>studentRow(s)).join('')}</tbody></table></div><p class="teacher-note section">Accounts, attempts, writing samples and mastery evidence are stored in Railway PostgreSQL. Teachers can reset passwords but cannot view current passwords.</p>`;$('addStudent').onclick=openAddStudent;document.querySelectorAll('[data-review-student]').forEach(b=>b.onclick=()=>openStudentDetail(b.dataset.reviewStudent))}
function studentRow(s){const w=weakest(s.id);return `<tr><td><div class="student-cell"><div class="avatar">${s.name[0]}</div><div><strong>${escapeHtml(s.name)}</strong><div class="muted">@${escapeHtml(s.username)}</div></div></div></td><td>${completionPct(s.id)}%</td><td>${mastery(s.id,'vocabulary')}%</td><td>${mastery(s.id,'grammar')}%</td><td>${mastery(s.id,'listening')}%</td><td>${mastery(s.id,'writing')}%</td><td>${w.label} ${w.score}%</td><td><button class="ghost-btn" data-review-student="${s.id}">Review</button></td></tr>`}
function openAddStudent(){showModal(`<div class="section-head"><div><p class="eyebrow">Teacher action</p><h3>Add student</h3></div><button class="icon-btn" data-close>×</button></div><form id="studentForm" class="form-grid"><label>Student name<input id="newName" required></label><label>Username<input id="newUsername" required placeholder="e.g. ahmed.ali"></label><label>Class<select id="newClass"><option value="c1">Fluency Foundations</option></select></label><button class="primary-btn" type="submit">Create student access</button></form><div id="createResult"></div>`);document.querySelector('[data-close]').onclick=closeModal;$('studentForm').onsubmit=async e=>{e.preventDefault();const name=$('newName').value.trim(),username=$('newUsername').value.trim().toLowerCase();try{const r=await api('/api/teacher/students',{method:'POST',body:JSON.stringify({name,username,classId:'c1'})});await refreshState();$('createResult').innerHTML=`<div class="feedback good"><strong>Student created.</strong><br>Username: <code>${escapeHtml(r.username)}</code><br>Temporary password: <code>${escapeHtml(r.temporaryPassword)}</code><br><small>Share it privately. The current password is never shown again.</small></div>`}catch(err){$('createResult').innerHTML=`<div class="feedback bad">${escapeHtml(err.message)}</div>`}}}
function openStudentDetail(id){const db=getDB(),s=db.users.find(u=>u.id===id),w=weakest(id),ats=attempts(id).slice(-10).reverse();showModal(`<div class="section-head"><div><p class="eyebrow">Student review</p><h3>${escapeHtml(s.name)}</h3></div><button class="icon-btn" data-close>×</button></div><div class="grid grid-4 compact-grid">${['vocabulary','grammar','listening','writing'].map(k=>skillCard(cap(k),mastery(id,k),'Mastery')).join('')}</div><div class="weakness section"><strong>Priority: ${w.label} · ${w.score}%</strong><span>${w.tip}</span></div><div class="section-head section"><div><h3>Recent attempts</h3><p>Evidence from workbook activity.</p></div><button class="ghost-btn" id="resetPass">Reset password</button></div>${ats.length?ats.map(a=>`<div class="attempt-row"><div><strong>Lesson ${lesson(a.lessonId).number} · ${cap(a.skill)} ${(a.tags||[]).includes('boost:activity')?'<span class="pill teal">Boost</span>':''}</strong><span>${new Date(a.at).toLocaleString()}</span></div><strong>${a.score}%</strong></div>`).join(''):'<p class="muted">No activity attempts yet.</p>'}<div id="resetResult"></div>`);document.querySelector('[data-close]').onclick=closeModal;$('resetPass').onclick=async()=>{try{const r=await api(`/api/teacher/students/${id}/reset-password`,{method:'POST'});$('resetResult').innerHTML=`<div class="feedback good">Temporary password reset to <code>${escapeHtml(r.temporaryPassword)}</code>. Share it privately.</div>`}catch(e){$('resetResult').innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}}
function classes(){const sts=classStudents();title('Course management','Classes');$('content').innerHTML=`<div class="card"><div class="section-head"><div><span class="pill teal">Active cohort</span><h3>Fluency Foundations</h3><p>${COURSE.level} · Module 1 · ${COURSE.lessons.length} topics · ${sts.length} students</p></div><strong>${Math.round(sts.reduce((a,s)=>a+completionPct(s.id),0)/sts.length)}% average completion</strong></div><div class="lesson-admin-grid">${COURSE.lessons.map(l=>{const avg=Math.round(sts.reduce((a,s)=>a+lessonProgress(s.id,l.id),0)/sts.length);return `<div class="card"><span class="pill">Topic ${l.number} · Week ${l.week}</span><h3>${l.title}</h3><p>${l.outcome}</p><strong>${avg}% class completion</strong>${progress(avg)}</div>`}).join('')}</div></div>`}
function aggregateWeaknesses(){const map={};classStudents().forEach(s=>{const w=weakest(s.id);map[w.key]=map[w.key]||{key:w.key,label:w.label,count:0,total:0};map[w.key].count++;map[w.key].total+=w.score});return Object.values(map).map(x=>({...x,avg:Math.round(x.total/x.count)})).sort((a,b)=>b.count-a.count||a.avg-b.avg)}
function weaknesses(){const areas=aggregateWeaknesses();title('Teacher intelligence','Weakness map');$('content').innerHTML=`<div class="grid grid-2"><div class="card"><h3>Class-wide weaknesses</h3><p class="muted">Prioritised by how many students have each skill as their lowest area.</p>${areas.map(a=>`<div class="question"><div style="display:flex;justify-content:space-between"><strong>${a.label}</strong><span class="pill ${a.avg<65?'gold':'teal'}">${a.count} student${a.count!==1?'s':''}</span></div><div style="margin-top:10px">${progress(a.avg)}</div><small class="muted">Average mastery ${a.avg}%</small></div>`).join('')}</div><div><div class="recommendation"><p class="eyebrow">Best use of live time</p><h3>${areas[0]?.label||'Collect more evidence'}</h3><p>${areas[0]?`Start with a 10-minute revision targeting ${areas[0].label.toLowerCase()}. Then return immediately to the live speaking mission.`:'Have students complete workbook activities first.'}</p></div><div class="card section"><h3>Student-level priorities</h3>${classStudents().map(s=>`<p><strong>${s.name}:</strong> ${weakest(s.id).label} ${weakest(s.id).score}%</p>`).join('')}</div></div></div>`}
function reports(){const sts=classStudents(),ats=getDB().attempts;title('Evidence','Reports');$('content').innerHTML=`<div class="grid grid-3">${metric('Workbook completion',Math.round(sts.reduce((a,s)=>a+completionPct(s.id),0)/sts.length)+'%','Module 1')}${metric('Average mastery',Math.round(sts.reduce((a,s)=>a+overall(s.id),0)/sts.length)+'%','4 tracked skills')}${metric('Attempts saved',ats.length,'Practice evidence')}</div><section class="section card"><div class="section-head"><div><h3>Evidence by student</h3><p>Completion, mastery and practice attempts.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Completion</th><th>Overall</th><th>Attempts</th><th>Writing samples</th><th>Primary focus</th></tr></thead><tbody>${sts.map(s=>`<tr><td>${s.name}</td><td>${completionPct(s.id)}%</td><td>${overall(s.id)}%</td><td>${attempts(s.id).length}</td><td>${Object.keys(getDB().writing?.[s.id]||{}).length}</td><td>${weakest(s.id).label}</td></tr>`).join('')}</tbody></table></div></section>`}
function leaderboard(teacher){title('Motivation','Class leaderboard');const data=classStudents().map(s=>({...s,points:points(s.id),completion:completionPct(s.id)})).sort((a,b)=>b.points-a.points);$('content').innerHTML=`<div class="card"><div class="section-head"><div><h3>Fluency Foundations · Module 1</h3><p>Points reward completion, attempts and successful practice — not English level alone.</p></div><span class="pill gold">Weekly</span></div>${data.map((s,i)=>`<div class="leader-row ${s.id===session.id&&!teacher?'me':''}"><div class="rank">${i+1}</div><div class="student-cell"><div class="avatar">${s.name[0]}</div><div><strong>${s.name}${s.id===session.id&&!teacher?' · You':''}</strong><div class="muted">${s.completion}% workbook complete</div></div></div><strong>${s.points} pts</strong></div>`).join('')}</div>`}
function showModal(html){let m=$('modalRoot');if(!m){m=document.createElement('div');m.id='modalRoot';document.body.appendChild(m)}m.innerHTML=`<div class="modal-backdrop"><div class="modal-card">${html}</div></div>`;m.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()}}
function closeModal(){const m=$('modalRoot');if(m)m.innerHTML=''}
function escapeAttr(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')} function escapeHtml(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
